import { defineMessages } from "./catalog.ts";

// Original source-bound SRD 5.1 translations; canonical mechanics remain untouched.
export const SPELL_HELP_MESSAGES = defineMessages({
  "spellHelp.native.fire-bolt": {
    "en": "You hurl a mote of fire at a creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 fire damage. A flammable object hit by this spell ignites if it isn't being worn or carried.\n\nThis spell's damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).",
    "zh-CN": "你向施法距离内的一个生物或物体掷出一团火焰。对目标进行一次远程法术攻击。命中时，目标受到 1d10 点火焰伤害。被此法术命中的易燃物体若未被穿戴或携带，便会燃烧。\n\n此法术的伤害在你达到 5 级时增加 1d10（2d10），11 级时增加至 3d10，17 级时增加至 4d10。"
  },
  "spellHelp.native.light": {
    "en": "You touch one object that is no larger than 10 feet in any dimension. Until the spell ends, the object sheds bright light in a 20-foot radius and dim light for an additional 20 feet. The light can be colored as you like. Completely covering the object with something opaque blocks the light. The spell ends if you cast it again or dismiss it as an action.\n\nIf you target an object held or worn by a hostile creature, that creature must succeed on a Dexterity saving throw to avoid the spell.",
    "zh-CN": "你触碰一个任一方向尺寸都不超过 10 英尺的物体。法术结束前，该物体在 20 英尺半径内发出明亮光照，并在其外侧另一个 20 英尺范围内发出微光。光的颜色由你决定。用不透明物体完全遮住目标即可挡住光。你再次施放此法术，或以一个动作解除它时，法术结束。\n\n如果目标物体被一个敌对生物持握或穿戴，该生物必须成功通过一次敏捷豁免，才能避开此法术。"
  },
  "spellHelp.native.mage-hand": {
    "en": "A spectral, floating hand appears at a point you choose within range. The hand lasts for the duration or until you dismiss it as an action. The hand vanishes if it is ever more than 30 feet away from you or if you cast this spell again.\n\nYou can use your action to control the hand. You can use the hand to manipulate an object, open an unlocked door or container, stow or retrieve an item from an open container, or pour the contents out of a vial. You can move the hand up to 30 feet each time you use it.\n\nThe hand can't attack, activate magic items, or carry more than 10 pounds.",
    "zh-CN": "一只幽灵般的漂浮手掌出现在施法距离内你选定的一点。它在法术持续时间内存在，或直到你以一个动作解除它。如果它距离你超过 30 英尺，或你再次施放此法术，手掌便会消失。\n\n你可以用一个动作控制手掌，使其操作物体、打开未上锁的门或容器、从打开的容器中取出或放入物品，或倒出小瓶中的东西。每次使用手掌时，你可以使其移动至多 30 英尺。\n\n手掌不能攻击、启动魔法物品，也不能携带超过 10 磅的物品。"
  },
  "spellHelp.native.cure-wounds": {
    "en": "A creature you touch regains a number of hit points equal to 1d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the healing increases by 1d8 for each slot level above 1st.",
    "zh-CN": "你触碰的一个生物恢复生命值，数值等于 1d8 + 你的施法属性调整值。此法术对不死生物和构装体无效。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，治疗量便增加 1d8。"
  },
  "spellHelp.native.detect-magic": {
    "en": "For the duration, you sense the presence of magic within 30 feet of you. If you sense magic in this way, you can use your action to see a faint aura around any visible creature or object in the area that bears magic, and you learn its school of magic, if any.\n\nThe spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt.",
    "zh-CN": "在法术持续时间内，你能感知自身周围 30 英尺内是否存在魔法。如果以此方式感知到魔法，你可以用一个动作，看见区域内带有魔法且你能看见的生物或物体周围的微弱灵光，并得知其魔法学派（如果有）。\n\n此法术能穿透大多数障碍，但会被 1 英尺厚的石头、1 英寸厚的普通金属、一层薄铅板，或 3 英尺厚的木材或泥土阻挡。"
  },
  "spellHelp.native.mage-armor": {
    "en": "You touch a willing creature who isn't wearing armor, and a protective magical force surrounds it until the spell ends. The target's base AC becomes 13 + its Dexterity modifier. The spell ends if the target dons armor or if you dismiss the spell as an action.",
    "zh-CN": "你触碰一个未穿着护甲且自愿接受法术的生物。一股具有保护作用的魔法力量环绕着它，直到法术结束。目标的基础护甲等级变为 13 + 其敏捷调整值。如果目标穿上护甲，或你以一个动作解除此法术，法术便会结束。"
  },
  "spellHelp.native.magic-missile": {
    "en": "You create three glowing darts of magical force. Each dart hits a creature of your choice that you can see within range. A dart deals 1d4 + 1 force damage to its target. The darts all strike simultaneously, and you can direct them to hit one creature or several.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the spell creates one more dart for each slot level above 1st.",
    "zh-CN": "你创造出三枚发光的魔法力场飞弹。每枚飞弹都会命中施法距离内你选定且能看见的一个生物。每枚飞弹对目标造成 1d4 + 1 点力场伤害。所有飞弹同时命中，你可以让它们击中同一个生物，也可以分配给多个生物。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，便额外产生一枚飞弹。"
  },
  "spellHelp.native.shield": {
    "en": "An invisible barrier of magical force appears and protects you. Until the start of your next turn, you have a +5 bonus to AC, including against the triggering attack, and you take no damage from *magic missile*.",
    "zh-CN": "一道无形的魔法力场屏障出现并保护你。直到你的下一回合开始，你的护甲等级获得 +5 加值，包括对触发此法术的那次攻击生效；你也不会受到*魔法飞弹*的伤害。"
  },
  "spellHelp.native.druidcraft": {
    "en": "Whispering to the spirits of nature, you create one of the following effects within range:\n\n- You create a tiny, harmless sensory effect that predicts what the weather will be at your location for the next 24 hours. The effect might manifest as a golden orb for clear skies, a cloud for rain, falling snowflakes for snow, and so on. This effect persists for 1 round.\n- You instantly make a flower blossom, a seed pod open, or a leaf bud bloom.\n- You create an instantaneous, harmless sensory effect, such as falling leaves, a puff of wind, the sound of a small animal, or the faint odor of skunk. The effect must fit in a 5-foot cube.\n- You instantly light or snuff out a candle, a torch, or a small campfire.",
    "zh-CN": "你向自然之灵低声祈语，在施法距离内创造以下效果之一：\n\n- 创造一个微小、无害的感官效果，预测你所在地点未来 24 小时的天气。例如，金色光球代表晴天，云朵代表雨天，飘落的雪花代表下雪。此效果持续 1 轮。\n- 使一朵花立刻绽放、一个种荚打开，或一个叶芽展开。\n- 创造一个瞬间、无害的感官效果，例如落叶、一阵微风、小动物的叫声，或淡淡的臭鼬气味。效果必须容纳在边长 5 英尺的立方体内。\n- 立刻点燃或熄灭一支蜡烛、一根火把或一小堆篝火。"
  },
  "spellHelp.native.guidance": {
    "en": "You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one ability check of its choice. It can roll the die before or after making the ability check. The spell then ends.",
    "zh-CN": "你触碰一个自愿接受法术的生物。法术结束前，目标可以在自己选择的一次属性检定中掷 1d4，并将结果加到该检定上，仅限一次。目标可以在进行属性检定之前或之后掷这枚骰子。随后法术结束。"
  },
  "spellHelp.native.mending": {
    "en": "This spell repairs a single break or tear in an object you touch, such as a broken chain link, two halves of a broken key, a torn cloak, or a leaking wineskin. As long as the break or tear is no larger than 1 foot in any dimension, you mend it, leaving no trace of the former damage.\n\nThis spell can physically repair a magic item or construct, but the spell can't restore magic to such an object.",
    "zh-CN": "此法术修复你触碰的物体上的一处断裂或撕裂，例如断开的链环、断成两半的钥匙、撕破的斗篷或漏酒的酒囊。只要损坏处在任何方向上都不超过 1 英尺，你就能将其修复，不留原先损坏的痕迹。\n\n此法术能修复魔法物品或构装体的实体损伤，但不能恢复其魔法。"
  },
  "spellHelp.native.poison-spray": {
    "en": "You extend your hand toward a creature you can see within range and project a puff of noxious gas from your palm. The creature must succeed on a Constitution saving throw or take 1d12 poison damage.\n\nThis spell's damage increases by 1d12 when you reach 5th level (2d12), 11th level (3d12), and 17th level (4d12).",
    "zh-CN": "你向施法距离内一个能看见的生物伸出手，从掌心喷出一团毒气。该生物必须成功通过一次体质豁免，否则受到 1d12 点毒素伤害。\n\n此法术的伤害在你达到 5 级时增加 1d12（2d12），11 级时增加至 3d12，17 级时增加至 4d12。"
  },
  "spellHelp.native.prestidigitation": {
    "en": "This spell is a minor magical trick that novice spellcasters use for practice. You create one of the following magical effects within Range:\n\n- You create an instantaneous, harmless sensory effect, such as a shower of sparks, a puff of wind, faint musical notes, or an odd odor.\n- You instantaneously light or snuff out a candle, a torch, or a small campfire.\n- You instantaneously clean or soil an object no larger than 1 cubic foot.\n- You chill, warm, or flavor up to 1 cubic foot of nonliving material for 1 hour.\n- You make a color, a small mark, or a symbol appear on an object or a surface for 1 hour.\n- You create a nonmagical trinket or an illusory image that can fit in your hand and that lasts until the end of your next turn.\n\nIf you cast this spell multiple times, you can have up to three of its non-instantaneous effects active at a time, and you can dismiss such an effect as an action.",
    "zh-CN": "这是初学施法者练习时使用的小魔法。你在施法距离内创造以下魔法效果之一：\n\n- 创造一个瞬间、无害的感官效果，例如一阵火花、一股微风、微弱的音符或奇怪的气味。\n- 立刻点燃或熄灭一支蜡烛、一根火把或一小堆篝火。\n- 立刻清洁或弄脏一个体积不超过 1 立方英尺的物体。\n- 使至多 1 立方英尺的非生命物质变冷、变暖或改变味道，持续 1 小时。\n- 使一个物体或表面出现颜色、小记号或符号，持续 1 小时。\n- 创造一个能放在手中的非魔法小饰物或幻影，持续到你的下一回合结束。\n\n多次施放此法术时，你可以同时维持至多 3 个非瞬间效果，并能以一个动作解除其中一个。"
  },
  "spellHelp.native.ray-of-frost": {
    "en": "A frigid beam of blue-white light streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes 1d8 cold damage, and its speed is reduced by 10 feet until the start of your next turn.\n\nThe spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).",
    "zh-CN": "一道寒冷的蓝白色光束射向施法距离内的一个生物。对目标进行一次远程法术攻击。命中时，目标受到 1d8 点冷冻伤害，速度降低 10 英尺，持续到你的下一回合开始。\n\n此法术的伤害在你达到 5 级时增加 1d8（2d8），11 级时增加至 3d8，17 级时增加至 4d8。"
  },
  "spellHelp.native.resistance": {
    "en": "You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one saving throw of its choice. It can roll the die before or after making the saving throw. The spell then ends.",
    "zh-CN": "你触碰一个自愿接受法术的生物。法术结束前，目标可以在自己选择的一次豁免中掷 1d4，并将结果加到该豁免上，仅限一次。目标可以在进行豁免之前或之后掷这枚骰子。随后法术结束。"
  },
  "spellHelp.native.sacred-flame": {
    "en": "Flame-like radiance descends on a creature that you can see within range. The target must succeed on a Dexterity saving throw or take 1d8 radiant damage. The target gains no benefit from cover for this saving throw.\n\nThe spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).",
    "zh-CN": "火焰般的光辉降临到施法距离内一个你能看见的生物身上。目标必须成功通过一次敏捷豁免，否则受到 1d8 点光耀伤害。目标在这次豁免中不能获得掩护带来的好处。\n\n此法术的伤害在你达到 5 级时增加 1d8（2d8），11 级时增加至 3d8，17 级时增加至 4d8。"
  },
  "spellHelp.native.shocking-grasp": {
    "en": "Lightning springs from your hand to deliver a shock to a creature you try to touch. Make a melee spell attack against the target. You have advantage on the attack roll if the target is wearing armor made of metal. On a hit, the target takes 1d8 lightning damage, and it can't take reactions until the start of its next turn.\n\nThe spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).",
    "zh-CN": "闪电从你手中迸发，电击你试图触碰的生物。对目标进行一次近战法术攻击。如果目标穿着金属制成的护甲，你的攻击检定具有优势。命中时，目标受到 1d8 点闪电伤害，并且直到它的下一回合开始前都不能执行反应。\n\n此法术的伤害在你达到 5 级时增加 1d8（2d8），11 级时增加至 3d8，17 级时增加至 4d8。"
  },
  "spellHelp.native.thaumaturgy": {
    "en": "You manifest a minor wonder, a sign of supernatural power, within range. You create one of the following magical effects within Range:\n\n- Your voice booms up to three times as loud as normal for 1 minute.\n- You cause flames to flicker, brighten, dim, or change color for 1 minute.\n- You cause harmless tremors in the ground for 1 minute.\n- You create an instantaneous sound that originates from a point of your choice within range, such as a rumble of thunder, the cry of a raven, or ominous whispers.\n- You instantaneously cause an unlocked door or window to fly open or slam shut.\n- You alter the appearance of your eyes for 1 minute. If you cast this spell multiple times, you can have up to three of its 1-minute effects active at a time, and you can dismiss such an effect as an action.",
    "zh-CN": "你在施法距离内显现一项小奇迹，展露超自然力量。你创造以下魔法效果之一：\n\n- 使你的声音变得洪亮，音量至多为平常的 3 倍，持续 1 分钟。\n- 使火焰闪烁、变亮、变暗或改变颜色，持续 1 分钟。\n- 使地面产生无害的震动，持续 1 分钟。\n- 使施法距离内你选定的一点瞬间发出声音，例如雷鸣、渡鸦的叫声或不祥的低语。\n- 使一扇未上锁的门或窗立刻打开或砰然关上。\n- 改变你的双眼外观，持续 1 分钟。多次施放此法术时，你可以同时维持至多 3 个持续 1 分钟的效果，并能以一个动作解除其中一个。"
  },
  "spellHelp.native.bane": {
    "en": "Up to three creatures of your choice that you can see within range must make Charisma saving throws. Whenever a target that fails this saving throw makes an attack roll or a saving throw before the spell ends, the target must roll a d4 and subtract the number rolled from the attack roll or saving throw.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st.",
    "zh-CN": "施法距离内至多 3 个你选定且能看见的生物必须进行魅力豁免。未通过豁免的目标在法术结束前，每次进行攻击检定或豁免时，都必须掷 1d4，并从该攻击检定或豁免中减去结果。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，就能额外指定一个目标。"
  },
  "spellHelp.native.bless": {
    "en": "You bless up to three creatures of your choice within range. Whenever a target makes an attack roll or a saving throw before the spell ends, the target can roll a d4 and add the number rolled to the attack roll or saving throw.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st.",
    "zh-CN": "你祝福施法距离内至多 3 个你选定的生物。法术结束前，目标每次进行攻击检定或豁免时，都可以掷 1d4，并将结果加到该攻击检定或豁免上。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，就能额外指定一个目标。"
  },
  "spellHelp.native.burning-hands": {
    "en": "As you hold your hands with thumbs touching and fingers spread, a thin sheet of flames shoots forth from your outstretched fingertips. Each creature in a 15-foot cone must make a Dexterity saving throw. A creature takes 3d6 fire damage on a failed save, or half as much damage on a successful one.\n\nThe fire ignites any flammable objects in the area that aren't being worn or carried.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st.",
    "zh-CN": "你将双手拇指相抵、其余手指张开，一片火焰从伸出的指尖喷出。15 英尺锥形区域内的每个生物都必须进行敏捷豁免。豁免失败的生物受到 3d6 点火焰伤害；豁免成功则受到一半伤害。\n\n火焰会点燃区域内未被穿戴或携带的易燃物体。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，伤害便增加 1d6。"
  },
  "spellHelp.native.charm-person": {
    "en": "You attempt to charm a humanoid you can see within range. It must make a Wisdom saving throw, and does so with advantage if you or your companions are fighting it. If it fails the saving throw, it is charmed by you until the spell ends or until you or your companions do anything harmful to it. The charmed creature regards you as a friendly acquaintance. When the spell ends, the creature knows it was charmed by you.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st. The creatures must be within 30 feet of each other when you target them.",
    "zh-CN": "你试图魅惑施法距离内一个能看见的类人生物。它必须进行感知豁免；如果你或你的同伴正在与它战斗，它在这次豁免中具有优势。豁免失败时，它被你魅惑，直到法术结束，或你及你的同伴对它做出任何有害行为。被魅惑的生物将你视为友善的熟人。法术结束时，该生物会知道自己曾被你魅惑。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，就能额外指定一个目标。指定目标时，这些生物彼此之间的距离必须在 30 英尺以内。"
  },
  "spellHelp.native.command": {
    "en": "You speak a one-word command to a creature you can see within range. The target must succeed on a Wisdom saving throw or follow the command on its next turn. The spell has no effect if the target is undead, if it doesn't understand your language, or if your command is directly harmful to it.\n\nSome typical commands and their effects follow. You might issue a command other than one described here. If you do so, the GM determines how the target behaves. If the target can't follow your command, the spell ends.\n\n***Approach***. The target moves toward you by the shortest and most direct route, ending its turn if it moves within 5 feet of you.\n\n***Drop***. The target drops whatever it is holding and then ends its turn.\n\n***Flee***. The target spends its turn moving away from you by the fastest available means.\n\n***Grovel***. The target falls prone and then ends its turn.\n\n***Halt***. The target doesn't move and takes no actions.\n\nA flying creature stays aloft, provided that it is able to do so. If it must move to stay aloft, it flies the minimum distance needed to remain in the air.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you can affect one additional creature for each slot level above 1st. The creatures must be within 30 feet of each other when you target them.",
    "zh-CN": "你向施法距离内一个能看见的生物发出一个词的命令。目标必须成功通过一次感知豁免，否则在它的下一回合服从命令。如果目标是不死生物、不理解你的语言，或命令会直接伤害它，此法术无效。\n\n下面列出一些常见命令及其效果。你也可以发出其他命令，由 DM 决定目标如何行动。如果目标无法服从命令，法术结束。\n\n***靠近。*** 目标沿最短、最直接的路线向你移动；进入你周围 5 英尺内后，它的回合结束。\n\n***丢下。*** 目标丢下手中持握的东西，随后结束回合。\n\n***逃跑。*** 目标以可用的最快方式，在它的回合里远离你。\n\n***趴下。*** 目标倒地，随后结束回合。\n\n***停止。*** 目标不移动，也不执行动作。\n\n飞行生物若能停留在空中，就会保持飞行。如果必须移动才能维持飞行，它会飞行保持在空中所需的最短距离。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，就能额外影响一个生物。指定目标时，这些生物彼此之间的距离必须在 30 英尺以内。"
  },
  "spellHelp.native.disguise-self": {
    "en": "You make yourself-including your clothing, armor, weapons, and other belongings on your person- look different until the spell ends or until you use your action to dismiss it. You can seem 1 foot shorter or taller and can appear thin, fat, or in between. You can't change your body type, so you must adopt a form that has the same basic arrangement of limbs. Otherwise, the extent of the illusion is up to you.\n\nThe changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to your outfit, objects pass through the hat, and anyone who touches it would feel nothing or would feel your head and hair. If you use this spell to appear thinner than you are, the hand of someone who reaches out to touch you would bump into you while it was seemingly still in midair.\n\nTo discern that you are disguised, a creature can use its action to inspect your appearance and must succeed on an Intelligence (Investigation) check against your spell save DC.",
    "zh-CN": "你使自己以及身上的衣服、护甲、武器和其他物品呈现不同的外观，直到法术结束，或你以一个动作解除它。你可以看起来比实际矮或高 1 英尺，也可以显得瘦、胖或介于两者之间。你不能改变身体类型，因此采用的形态必须具有相同的基本肢体结构。除此之外，幻象的具体外观由你决定。\n\n此法术造成的变化无法经受实体接触检验。例如，如果你用它在装束上增加一顶帽子，物体会穿过帽子；触碰帽子的人会摸不到东西，或摸到你的头和头发。如果你让自己显得更瘦，伸手触碰你的人会在手看起来仍悬在半空时碰到你的身体。\n\n一个生物可以用一个动作检查你的外观，并以你的法术豁免 DC 为难度进行智力（调查）检定。检定成功便能识破你的伪装。"
  },
  "spellHelp.native.entangle": {
    "en": "Grasping weeds and vines sprout from the ground in a 20-foot square starting from a point within range. For the duration, these plants turn the ground in the area into difficult terrain.\n\nA creature in the area when you cast the spell must succeed on a Strength saving throw or be restrained by the entangling plants until the spell ends. A creature restrained by the plants can use its action to make a Strength check against your spell save DC. On a success, it frees itself.\n\nWhen the spell ends, the conjured plants wilt away.",
    "zh-CN": "抓握的杂草和藤蔓从地面长出，覆盖以施法距离内一点为起点、边长 20 英尺的正方形区域。在法术持续时间内，这些植物使区域内的地面成为困难地形。\n\n施放法术时位于区域内的生物必须成功通过一次力量豁免，否则被植物束缚，直到法术结束。被植物束缚的生物可以用一个动作，以你的法术豁免 DC 为难度进行力量检定；成功便能挣脱。\n\n法术结束时，召来的植物枯萎消失。"
  },
  "spellHelp.native.faerie-fire": {
    "en": "Each object in a 20-foot cube within range is outlined in blue, green, or violet light (your choice). Any creature in the area when the spell is cast is also outlined in light if it fails a Dexterity saving throw. For the duration, objects and affected creatures shed dim light in a 10-foot radius.\n\nAny attack roll against an affected creature or object has advantage if the attacker can see it, and the affected creature or object can't benefit from being invisible.",
    "zh-CN": "施法距离内一个边长 20 英尺的立方体中的每个物体，都被蓝色、绿色或紫色的光勾勒出轮廓，颜色由你选择。施放法术时位于区域内的生物若未通过敏捷豁免，也会被光勾勒。在法术持续时间内，物体和受影响的生物在周围 10 英尺半径内发出微光。\n\n只要攻击者能看见受影响的生物或物体，对其进行的任何攻击检定都具有优势；受影响的生物或物体也不能获得隐形带来的好处。"
  },
  "spellHelp.native.feather-fall": {
    "en": "Choose up to five falling creatures within range. A falling creature's rate of descent slows to 60 feet per round until the spell ends. If the creature lands before the spell ends, it takes no falling damage and can land on its feet, and the spell ends for that creature.",
    "zh-CN": "选择施法距离内至多 5 个正在坠落的生物。直到法术结束，它们的下落速度减慢至每轮 60 英尺。如果一个生物在法术结束前落地，它不会受到坠落伤害，并能双脚着地；随后此法术对该生物结束。"
  },
  "spellHelp.native.goodberry": {
    "en": "Up to ten berries appear in your hand and are infused with magic for the duration. A creature can use its action to eat one berry. Eating a berry restores 1 hit point, and the berry provides enough nourishment to sustain a creature for one day.\n\nThe berries lose their potency if they have not been consumed within 24 hours of the casting of this spell.",
    "zh-CN": "至多 10 颗浆果出现在你手中，并在有效期内蕴含魔法。一个生物可以用一个动作吃下一颗浆果。食用一颗浆果可恢复 1 点生命值，并提供足够维持该生物一天的营养。\n\n施放此法术后 24 小时内未被吃掉的浆果会失去效力。"
  },
  "spellHelp.native.healing-word": {
    "en": "A creature of your choice that you can see within range regains hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on undead or constructs.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the healing increases by 1d4 for each slot level above 1st.",
    "zh-CN": "施法距离内一个你选定且能看见的生物恢复生命值，数值等于 1d4 + 你的施法属性调整值。此法术对不死生物和构装体无效。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，治疗量便增加 1d4。"
  },
  "spellHelp.native.silent-image": {
    "en": "You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 15-foot cube. The image appears at a spot within range and lasts for the duration. The image is purely visual; it isn't accompanied by sound, smell, or other sensory effects.\n\nYou can use your action to cause the image to move to any spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking.\n\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image.",
    "zh-CN": "你创造一个物体、生物或其他可见现象的影像，其尺寸不能超过边长 15 英尺的立方体。影像出现在施法距离内的一点，并在法术持续时间内存在。影像只有视觉效果，不伴随声音、气味或其他感官效果。\n\n你可以用一个动作，使影像移动到施法距离内的任意一点。移动时，你可以改变影像的外观，使其移动显得自然。例如，移动一个生物的影像时，可以让它看起来正在行走。\n\n与影像发生实体接触会暴露它是幻象，因为物体可以穿过它。一个生物可以用一个动作检查影像，并以你的法术豁免 DC 为难度进行智力（调查）检定；成功便能识破幻象。识破幻象的生物可以看穿影像。"
  },
  "spellHelp.native.sleep": {
    "en": "This spell sends creatures into a magical slumber. Roll 5d8; the total is how many hit points of creatures this spell can affect. Creatures within 20 feet of a point you choose within range are affected in ascending order of their current hit points (ignoring unconscious creatures).\n\nStarting with the creature that has the lowest current hit points, each creature affected by this spell falls unconscious until the spell ends, the sleeper takes damage, or someone uses an action to shake or slap the sleeper awake. Subtract each creature's hit points from the total before moving on to the creature with the next lowest hit points. A creature's hit points must be equal to or less than the remaining total for that creature to be affected.\n\nUndead and creatures immune to being charmed aren't affected by this spell.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, roll an additional 2d8 for each slot level above 1st.",
    "zh-CN": "此法术使生物陷入魔法沉睡。掷 5d8，结果总和决定此法术可以影响的生物生命值总量。以施法距离内你选定的一点为中心，20 英尺内的生物按当前生命值从低到高依次受到影响，忽略已经失去意识的生物。\n\n从当前生命值最低的生物开始，每个受影响的生物都失去意识，直到法术结束、受到伤害，或有人用一个动作摇晃或拍打它，将其唤醒。影响一个生物后，从剩余总量中减去该生物的生命值，再考虑生命值次低的生物。一个生物的生命值必须不超过剩余总量，才能受到影响。\n\n不死生物以及免疫魅惑的生物不受此法术影响。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，就额外掷 2d8。"
  },
  "spellHelp.native.thunderwave": {
    "en": "A wave of thunderous force sweeps out from you. Each creature in a 15-foot cube originating from you must make a Constitution saving throw. On a failed save, a creature takes 2d8 thunder damage and is pushed 10 feet away from you. On a successful save, the creature takes half as much damage and isn't pushed.\n\nIn addition, unsecured objects that are completely within the area of effect are automatically pushed 10 feet away from you by the spell's effect, and the spell emits a thunderous boom audible out to 300 feet.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st.",
    "zh-CN": "一股雷鸣般的冲击力从你身上向外扫出。以你为起点、边长 15 英尺的立方体内，每个生物都必须进行体质豁免。豁免失败时，生物受到 2d8 点雷鸣伤害，并被推离你 10 英尺；豁免成功时，受到一半伤害，且不会被推动。\n\n此外，完全位于效果区域内且未被固定的物体，会自动被推离你 10 英尺。此法术还会发出雷鸣般的巨响，在 300 英尺外都能听见。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，伤害便增加 1d8。"
  },
  "spellHelp.native.acid-splash": {
    "en": "You hurl a bubble of acid. Choose one creature you can see within range, or choose two creatures you can see within range that are within 5 feet of each other. A target must succeed on a Dexterity saving throw or take 1d6 acid damage.\n\nThis spell's damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6).",
    "zh-CN": "你掷出一团酸液。选择施法距离内一个能看见的生物，或选择两个你能看见且彼此相距不超过 5 英尺的生物。目标必须成功通过一次敏捷豁免，否则受到 1d6 点强酸伤害。\n\n此法术的伤害在你达到 5 级时增加 1d6（2d6），11 级时增加至 3d6，17 级时增加至 4d6。"
  },
  "spellHelp.native.chill-touch": {
    "en": "You create a ghostly, skeletal hand in the space of a creature within range. Make a ranged spell attack against the creature to assail it with the chill of the grave. On a hit, the target takes 1d8 necrotic damage, and it can't regain hit points until the start of your next turn. Until then, the hand clings to the target.\n\nIf you hit an undead target, it also has disadvantage on attack rolls against you until the end of your next turn.\n\nThis spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).",
    "zh-CN": "你在施法距离内一个生物所在的位置创造一只幽灵般的骷髅手。对该生物进行一次远程法术攻击，以墓穴的寒意侵袭它。命中时，目标受到 1d8 点黯蚀伤害，并且直到你的下一回合开始前都不能恢复生命值。在此之前，骷髅手一直附着在目标身上。\n\n如果命中的是不死生物，它对你的攻击检定还会具有劣势，持续到你的下一回合结束。\n\n此法术的伤害在你达到 5 级时增加 1d8（2d8），11 级时增加至 3d8，17 级时增加至 4d8。"
  },
  "spellHelp.native.dancing-lights": {
    "en": "You create up to four torch-sized lights within range, making them appear as torches, lanterns, or glowing orbs that hover in the air for the duration. You can also combine the four lights into one glowing vaguely humanoid form of Medium size. Whichever form you choose, each light sheds dim light in a 10-foot radius.\n\nAs a bonus action on your turn, you can move the lights up to 60 feet to a new spot within range. A light must be within 20 feet of another light created by this spell, and a light winks out if it exceeds the spell's range.",
    "zh-CN": "你在施法距离内创造至多 4 个火把大小的光源，使其呈现为火把、提灯或发光球体，并在法术持续时间内悬浮于空中。你也可以将这 4 个光源组合成一个大致呈类人形态的中型发光形体。无论选择何种形态，每个光源都会在 10 英尺半径内发出微光。\n\n在你的回合，你可以用一个附赠动作，将光源移动至多 60 英尺，到达施法距离内的新位置。每个光源都必须位于此法术创造的另一个光源周围 20 英尺以内；超出施法距离的光源会熄灭。"
  },
  "spellHelp.native.eldritch-blast": {
    "en": "A beam of crackling energy streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 force damage.\n\nThe spell creates more than one beam when you reach higher levels: two beams at 5th level, three beams at 11th level, and four beams at 17th level. You can direct the beams at the same target or at different ones. Make a separate attack roll for each beam.",
    "zh-CN": "一道噼啪作响的能量束射向施法距离内的一个生物。对目标进行一次远程法术攻击。命中时，目标受到 1d10 点力场伤害。\n\n达到更高等级后，此法术会创造多道能量束：5 级时为 2 道，11 级时为 3 道，17 级时为 4 道。你可以让它们攻击同一目标或不同目标，每道能量束分别进行攻击检定。"
  },
  "spellHelp.native.message": {
    "en": "You point your finger toward a creature within range and whisper a message. The target (and only the target) hears the message and can reply in a whisper that only you can hear.\n\nYou can cast this spell through solid objects if you are familiar with the target and know it is beyond the barrier. Magical silence, 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood blocks the spell. The spell doesn't have to follow a straight line and can travel freely around corners or through openings.",
    "zh-CN": "你用手指指向施法距离内的一个生物，低声传递一条讯息。只有目标能听见，并且它可以低声回复，回复只有你能听见。\n\n如果你熟悉目标，并知道它位于障碍物另一侧，就可以隔着实体物体施放此法术。魔法造成的寂静、1 英尺厚的石头、1 英寸厚的普通金属、一层薄铅板或 3 英尺厚的木材会阻挡法术。讯息不必沿直线传递，可以自由绕过转角或穿过开口。"
  },
  "spellHelp.native.minor-illusion": {
    "en": "You create a sound or an image of an object within range that lasts for the duration. The illusion also ends if you dismiss it as an action or cast this spell again.\n\nIf you create a sound, its volume can range from a whisper to a scream. It can be your voice, someone else's voice, a lion's roar, a beating of drums, or any other sound you choose. The sound continues unabated throughout the duration, or you can make discrete sounds at different times before the spell ends.\n\nIf you create an image of an object-such as a chair, muddy footprints, or a small chest-it must be no larger than a 5-foot cube. The image can't create sound, light, smell, or any other sensory effect. Physical interaction with the image reveals it to be an illusion, because things can pass through it.\n\nIf a creature uses its action to examine the sound or image, the creature can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the illusion becomes faint to the creature.",
    "zh-CN": "你在施法距离内创造一个声音或一个物体的影像，在法术持续时间内存在。你以一个动作解除幻象或再次施放此法术时，幻象也会结束。\n\n创造声音时，其音量可以从耳语到尖叫。声音可以是你或他人的嗓音、狮吼、鼓声或其他你选择的声音。它可以在整个持续时间内连续响起，也可以在法术结束前的不同时刻分别发声。\n\n创造物体影像时，例如椅子、泥泞脚印或小箱子，其尺寸不能超过边长 5 英尺的立方体。影像不能产生声音、光、气味或其他感官效果。与影像发生实体接触会暴露它是幻象，因为物体可以穿过它。\n\n一个生物可以用一个动作检查声音或影像，并以你的法术豁免 DC 为难度进行智力（调查）检定；成功便能识破幻象。识破幻象的生物会觉得幻象变得模糊微弱。"
  },
  "spellHelp.native.produce-flame": {
    "en": "A flickering flame appears in your hand. The flame remains there for the duration and harms neither you nor your equipment. The flame sheds bright light in a 10-foot radius and dim light for an additional 10 feet. The spell ends if you dismiss it as an action or if you cast it again.\n\nYou can also attack with the flame, although doing so ends the spell. When you cast this spell, or as an action on a later turn, you can hurl the flame at a creature within 30 feet of you. Make a ranged spell attack. On a hit, the target takes 1d8 fire damage.\n\nThis spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).",
    "zh-CN": "一团摇曳的火焰出现在你手中，在法术持续时间内存在，不会伤害你或你的装备。火焰在 10 英尺半径内发出明亮光照，并在其外侧另一个 10 英尺范围内发出微光。你以一个动作解除法术或再次施放它时，法术结束。\n\n你也可以用火焰攻击，但这样会结束法术。施放此法术时，或在之后的回合用一个动作，你可以将火焰掷向周围 30 英尺内的一个生物。进行一次远程法术攻击；命中时，目标受到 1d8 点火焰伤害。\n\n此法术的伤害在你达到 5 级时增加 1d8（2d8），11 级时增加至 3d8，17 级时增加至 4d8。"
  },
  "spellHelp.native.shillelagh": {
    "en": "The wood of a club or quarterstaff you are holding is imbued with nature's power. For the duration, you can use your spellcasting ability instead of Strength for the attack and damage rolls of melee attacks using that weapon, and the weapon's damage die becomes a d8. The weapon also becomes magical, if it isn't already. The spell ends if you cast it again or if you let go of the weapon.",
    "zh-CN": "你持握的一根木棒或长棍的木材被注入自然之力。在法术持续时间内，使用该武器进行近战攻击时，你可以用施法属性替代力量，计算攻击检定和伤害掷骰；武器的伤害骰变为 1d8。如果武器原本不是魔法武器，它也会成为魔法武器。你再次施放此法术或松开武器时，法术结束。"
  },
  "spellHelp.native.spare-the-dying": {
    "en": "You touch a living creature that has 0 hit points. The creature becomes stable. This spell has no effect on undead or constructs.",
    "zh-CN": "你触碰一个生命值为 0 的活着的生物，使其伤势稳定。此法术对不死生物和构装体无效。"
  },
  "spellHelp.native.true-strike": {
    "en": "You extend your hand and point a finger at a target in range. Your magic grants you a brief insight into the target's defenses. On your next turn, you gain advantage on your first attack roll against the target, provided that this spell hasn't ended.",
    "zh-CN": "你伸出手，用手指指向施法距离内的一个目标。魔法使你短暂洞悉目标的防御。只要此法术尚未结束，你在下一回合对该目标进行的第一次攻击检定便具有优势。"
  },
  "spellHelp.native.vicious-mockery": {
    "en": "You unleash a string of insults laced with subtle enchantments at a creature you can see within range. If the target can hear you (though it need not understand you), it must succeed on a Wisdom saving throw or take 1d4 psychic damage and have disadvantage on the next attack roll it makes before the end of its next turn.\n\nThis spell's damage increases by 1d4 when you reach 5th level (2d4), 11th level (3d4), and 17th level (4d4).",
    "zh-CN": "你对施法距离内一个能看见的生物发出一连串暗藏魔法的辱骂。如果目标能听见你，即使不理解你的话，也必须成功通过一次感知豁免，否则受到 1d4 点心灵伤害，并在它的下一回合结束前进行的下一次攻击检定中具有劣势。\n\n此法术的伤害在你达到 5 级时增加 1d4（2d4），11 级时增加至 3d4，17 级时增加至 4d4。"
  },
  "spellHelp.native.alarm": {
    "en": "You set an alarm against unwanted intrusion. Choose a door, a window, or an area within range that is no larger than a 20-foot cube. Until the spell ends, an alarm alerts you whenever a Tiny or larger creature touches or enters the warded area. When you cast the spell, you can designate creatures that won't set off the alarm. You also choose whether the alarm is mental or audible.\n\nA mental alarm alerts you with a ping in your mind if you are within 1 mile of the warded area. This ping awakens you if you are sleeping.\n\nAn audible alarm produces the sound of a hand bell for 10 seconds within 60 feet.",
    "zh-CN": "你设置一道警报，防范不受欢迎的闯入者。选择施法距离内的一扇门、一扇窗，或一个尺寸不超过边长 20 英尺立方体的区域。法术结束前，只要微型或更大的生物触碰或进入受保护区域，警报就会提醒你。施法时，你可以指定不会触发警报的生物，并选择心灵警报或声音警报。\n\n如果你位于受保护区域周围 1 英里以内，心灵警报会在你脑海中响起提示。熟睡时，这个提示也会唤醒你。\n\n声音警报会发出手铃声，持续 10 秒，周围 60 英尺内都能听见。"
  },
  "spellHelp.native.color-spray": {
    "en": "A dazzling array of flashing, colored light springs from your hand. Roll 6d10; the total is how many hit points of creatures this spell can effect. Creatures in a 15-foot cone originating from you are affected in ascending order of their current hit points (ignoring unconscious creatures and creatures that can't see).\n\nStarting with the creature that has the lowest current hit points, each creature affected by this spell is blinded until the end of your next turn. Subtract each creature's hit points from the total before moving on to the creature with the next lowest hit points. A creature's hit points must be equal to or less than the remaining total for that creature to be affected.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, roll an additional 2d10 for each slot level above 1st.",
    "zh-CN": "耀眼的彩色闪光从你手中迸发。掷 6d10，结果总和决定此法术可以影响的生物生命值总量。以你为起点的 15 英尺锥形区域内，生物按当前生命值从低到高依次受到影响，忽略已经失去意识或无法看见的生物。\n\n从当前生命值最低的生物开始，每个受影响的生物都目盲，直到你的下一回合结束。影响一个生物后，从剩余总量中减去它的生命值，再考虑生命值次低的生物。一个生物的生命值必须不超过剩余总量，才能受到影响。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，就额外掷 2d10。"
  },
  "spellHelp.native.comprehend-languages": {
    "en": "For the duration, you understand the literal meaning of any spoken language that you hear. You also understand any written language that you see, but you must be touching the surface on which the words are written. It takes about 1 minute to read one page of text.\n\nThis spell doesn't decode secret messages in a text or a glyph, such as an arcane sigil, that isn't part of a written language.",
    "zh-CN": "在法术持续时间内，你能理解听到的任何口语的字面含义。你也能理解看见的任何书面语言，但必须触碰写有文字的表面。阅读一页文字大约需要 1 分钟。\n\n此法术不能破解文字中的秘密讯息，也不能解读不属于书面语言的符文，例如奥术印记。"
  },
  "spellHelp.native.create-or-destroy-water": {
    "en": "You either create or destroy water.\n\n***Create Water***. You create up to 10 gallons of clean water within range in an open container. Alternatively, the water falls as rain in a 30-foot cube within range, extinguishing exposed flames in the area.\n\n***Destroy Water***. You destroy up to 10 gallons of water in an open container within range. Alternatively, you destroy fog in a 30-foot cube within range.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you create or destroy 10 additional gallons of water, or the size of the cube increases by 5 feet, for each slot level above 1st.",
    "zh-CN": "你可以创造或销毁水。\n\n***造水。*** 你在施法距离内一个敞开的容器中创造至多 10 加仑干净的水。也可以让水以雨的形式降在施法距离内一个边长 30 英尺的立方体区域中，熄灭区域内暴露的火焰。\n\n***销水。*** 你销毁施法距离内一个敞开的容器中至多 10 加仑的水。也可以消除施法距离内一个边长 30 英尺的立方体区域中的雾。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，创造或销毁的水便增加 10 加仑，或立方体的边长增加 5 英尺。"
  },
  "spellHelp.native.detect-evil-and-good": {
    "en": "For the duration, you know if there is an aberration, celestial, elemental, fey, fiend, or undead within 30 feet of you, as well as where the creature is located. Similarly, you know if there is a place or object within 30 feet of you that has been magically consecrated or desecrated.\n\nThe spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt.",
    "zh-CN": "在法术持续时间内，你能知道周围 30 英尺内是否存在异怪、天界生物、元素生物、精类、邪魔或不死生物，以及它们的位置。同样，你能知道周围 30 英尺内是否存在被魔法祝圣或亵渎的地点或物体。\n\n此法术能穿透大多数障碍，但会被 1 英尺厚的石头、1 英寸厚的普通金属、一层薄铅板，或 3 英尺厚的木材或泥土阻挡。"
  },
  "spellHelp.native.detect-poison-and-disease": {
    "en": "For the duration, you can sense the presence and location of poisons, poisonous creatures, and diseases within 30 feet of you. You also identify the kind of poison, poisonous creature, or disease in each case.\n\nThe spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt.",
    "zh-CN": "在法术持续时间内，你能感知周围 30 英尺内的毒素、有毒生物和疾病是否存在，以及它们的位置。你还能辨认每种毒素、有毒生物或疾病的种类。\n\n此法术能穿透大多数障碍，但会被 1 英尺厚的石头、1 英寸厚的普通金属、一层薄铅板，或 3 英尺厚的木材或泥土阻挡。"
  },
  "spellHelp.native.divine-favor": {
    "en": "Your prayer empowers you with divine radiance. Until the spell ends, your weapon attacks deal an extra 1d4 radiant damage on a hit.",
    "zh-CN": "你的祈祷使你获得神圣光辉的力量。法术结束前，你的武器攻击命中时额外造成 1d4 点光耀伤害。"
  },
  "spellHelp.native.expeditious-retreat": {
    "en": "This spell allows you to move at an incredible pace. When you cast this spell, and then as a bonus action on each of your turns until the spell ends, you can take the Dash action.",
    "zh-CN": "此法术使你能以惊人的速度移动。施放此法术时，以及法术结束前你的每个回合，你都可以用一个附赠动作执行疾走动作。"
  },
  "spellHelp.native.false-life": {
    "en": "Bolstering yourself with a necromantic facsimile of life, you gain 1d4 + 4 temporary hit points for the duration.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you gain 5 additional temporary hit points for each slot level above 1st.",
    "zh-CN": "你以死灵魔法模拟生命，强化自身，获得 1d4 + 4 点临时生命值，在法术持续时间内有效。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，获得的临时生命值便增加 5 点。"
  },
  "spellHelp.native.floating-disk": {
    "en": "This spell creates a circular, horizontal plane of force, 3 feet in diameter and 1 inch thick, that floats 3 feet above the ground in an unoccupied space of your choice that you can see within range. The disk remains for the duration, and can hold up to 500 pounds. If more weight is placed on it, the spell ends, and everything on the disk falls to the ground.\n\nThe disk is immobile while you are within 20 feet of it. If you move more than 20 feet away from it, the disk follows you so that it remains within 20 feet of you. It can move across uneven terrain, up or down stairs, slopes and the like, but it can't cross an elevation change of 10 feet or more. For example, the disk can't move across a 10-foot deep pit, nor could it leave such a pit if it was created at the bottom.\n\nIf you move more than 100 feet from the disk (typically because it can't move around an obstacle to follow you), the spell ends.",
    "zh-CN": "此法术在施法距离内一个你能看见且未被占据的位置，创造一个水平的圆形力场盘。圆盘直径 3 英尺、厚 1 英寸，悬浮在离地 3 英尺的高度。它在法术持续时间内存在，能承载至多 500 磅。如果放置的重量超过上限，法术结束，盘上的一切都会掉到地上。\n\n你位于圆盘周围 20 英尺以内时，它保持不动。你离开超过 20 英尺后，它会跟随你，使自身保持在你周围 20 英尺以内。圆盘可以越过不平整的地面、上下楼梯和斜坡等，但不能跨越 10 英尺或更大的高度差。例如，它不能越过一个深 10 英尺的坑；如果在坑底被创造出来，也不能离开这个坑。\n\n你距离圆盘超过 100 英尺时，法术结束。这通常发生在圆盘无法绕过障碍物跟随你时。"
  },
  "spellHelp.native.fog-cloud": {
    "en": "You create a 20-foot radius sphere of fog centered on a point within range. The sphere spreads around corners, and its area is heavily obscured. It lasts for the duration or until a wind of moderate or greater speed (at least 10 miles per hour) disperses it.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the radius of the fog increases by 20 feet for each slot level above 1st.",
    "zh-CN": "你以施法距离内的一点为中心，创造一个半径 20 英尺的球形雾区。雾会绕过转角扩散，其区域属于重度遮蔽。雾在法术持续时间内存在，或直到被中等或更强的风吹散，即风速至少每小时 10 英里。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，雾区半径便增加 20 英尺。"
  },
  "spellHelp.native.grease": {
    "en": "Slick grease covers the ground in a 10-foot square centered on a point within range and turns it into difficult terrain for the duration.\n\nWhen the grease appears, each creature standing in its area must succeed on a Dexterity saving throw or fall prone. A creature that enters the area or ends its turn there must also succeed on a Dexterity saving throw or fall prone.",
    "zh-CN": "以施法距离内一点为中心、边长 10 英尺的正方形地面被滑腻的油脂覆盖，在法术持续时间内成为困难地形。\n\n油脂出现时，站在区域内的每个生物都必须成功通过一次敏捷豁免，否则倒地。进入区域或在区域内结束回合的生物，也必须成功通过一次敏捷豁免，否则倒地。"
  },
  "spellHelp.native.guiding-bolt": {
    "en": "A flash of light streaks toward a creature of your choice within range. Make a ranged spell attack against the target. On a hit, the target takes 4d6 radiant damage, and the next attack roll made against this target before the end of your next turn has advantage, thanks to the mystical dim light glittering on the target until then.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st.",
    "zh-CN": "一道闪光射向施法距离内你选定的一个生物。对目标进行一次远程法术攻击。命中时，目标受到 4d6 点光耀伤害；目标身上闪烁的神秘微光还会使你的下一回合结束前，对它进行的下一次攻击检定具有优势。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，伤害便增加 1d6。"
  },
  "spellHelp.native.hellish-rebuke": {
    "en": "You point your finger, and the creature that damaged you is momentarily surrounded by hellish flames. The creature must make a Dexterity saving throw. It takes 2d10 fire damage on a failed save, or half as much damage on a successful one.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d10 for each slot level above 1st.",
    "zh-CN": "你伸出手指，伤害你的生物瞬间被地狱烈焰包围。该生物必须进行敏捷豁免。豁免失败时受到 2d10 点火焰伤害；豁免成功则受到一半伤害。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，伤害便增加 1d10。"
  },
  "spellHelp.native.animal-friendship": {
    "en": "This spell lets you convince a beast that you mean it no harm. Choose a beast that you can see within range. It must see and hear you. If the beast's Intelligence is 4 or higher, the spell fails. Otherwise, the beast must succeed on a Wisdom saving throw or be charmed by you for the spell's duration. If you or one of your companions harms the target, the spells ends.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you can affect one additional beast t level above 1st.",
    "zh-CN": "此法术让你向一个野兽表明自己没有恶意。选择施法距离内一个能看见的野兽；它必须能看见并听见你。如果它的智力为 4 或更高，法术失败。否则，它必须成功通过一次感知豁免，或在法术持续时间内被你魅惑。如果你或你的任何同伴伤害目标，法术结束。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，就能额外影响一个野兽。"
  },
  "spellHelp.native.find-familiar": {
    "en": "You gain the service of a familiar, a spirit that takes an animal form you choose: bat, cat, crab, frog (toad), hawk, lizard, octopus, owl, poisonous snake, fish (quipper), rat, raven, sea horse, spider, or weasel. Appearing in an unoccupied space within range, the familiar has the statistics of the chosen form, though it is a celestial, fey, or fiend (your choice) instead of a beast.\n\nYour familiar acts independently of you, but it always obeys your commands. In combat, it rolls its own initiative and acts on its own turn. A familiar can't attack, but it can take other actions as normal.\n\nWhen the familiar drops to 0 hit points, it disappears, leaving behind no physical form. It reappears after you cast this spell again.\n\nWhile your familiar is within 100 feet of you, you can communicate with it telepathically. Additionally, as an action, you can see through your familiar's eyes and hear what it hears until the start of your next turn, gaining the benefits of any special senses that the familiar has. During this time, you are deaf and blind with regard to your own senses.\n\nAs an action, you can temporarily dismiss your familiar. It disappears into a pocket dimension where it awaits your summons. Alternatively, you can dismiss it forever. As an action while it is temporarily dismissed, you can cause it to reappear in any unoccupied space within 30 feet of you.\n\nYou can't have more than one familiar at a time. If you cast this spell while you already have a familiar, you instead cause it to adopt a new form. Choose one of the forms from the above list. Your familiar transforms into the chosen creature.\n\nFinally, when you cast a spell with a range of touch, your familiar can deliver the spell as if it had cast the spell. Your familiar must be within 100 feet of you, and it must use its reaction to deliver the spell when you cast it. If the spell requires an attack roll, you use your attack modifier for the roll.",
    "zh-CN": "你获得一个魔宠的服侍。它是一个精魂，采用你选定的动物形态：蝙蝠、猫、蟹、蛙（蟾蜍）、鹰、蜥蜴、章鱼、猫头鹰、毒蛇、鱼（食人鱼）、鼠、渡鸦、海马、蜘蛛或鼬。魔宠出现在施法距离内一个未被占据的位置，使用所选形态的数据，但其生物类型是天界生物、精类或邪魔，由你选择，而不是野兽。\n\n魔宠独立行动，但始终服从你的命令。在战斗中，它单独掷先攻，并在自己的回合行动。魔宠不能攻击，但可以正常执行其他动作。\n\n魔宠的生命值降至 0 时便会消失，不留下实体。你再次施放此法术后，它会重新出现。\n\n魔宠位于你周围 100 英尺内时，你可以与它心灵交流。此外，你可以用一个动作，透过它的眼睛观察，并听见它听到的声音，直到你的下一回合开始；期间你获得魔宠拥有的任何特殊感官带来的好处，但你自身的感官处于耳聋和目盲状态。\n\n你可以用一个动作暂时遣散魔宠，使其进入一个袖珍位面，等待你的召唤；也可以永久遣散它。魔宠被暂时遣散期间，你可以用一个动作，使其重新出现在你周围 30 英尺内任意一个未被占据的位置。\n\n你不能同时拥有多个魔宠。如果已有魔宠时再次施放此法术，你会让它从上述列表中采用一个新形态，变为选定的生物。\n\n最后，施放施法距离为触碰的法术时，魔宠可以替你传递法术，视同由它施放。魔宠必须位于你周围 100 英尺内，并在你施法时使用它的反应来传递法术。如果法术需要攻击检定，使用你的攻击调整值进行检定。"
  },
  "spellHelp.native.heroism": {
    "en": "A willing creature you touch is imbued with bravery. Until the spell ends, the creature is immune to being frightened and gains temporary hit points equal to your spellcasting ability modifier at the start of each of its turns. When the spell ends, the target loses any remaining temporary hit points from this spell.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st.",
    "zh-CN": "你触碰的一个自愿接受法术的生物被注入勇气。法术结束前，它免疫恐慌，并在自己的每个回合开始时获得临时生命值，数值等于你的施法属性调整值。法术结束时，目标失去由此法术获得且尚未耗尽的临时生命值。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，就能额外指定一个目标。"
  },
  "spellHelp.native.hideous-laughter": {
    "en": "A creature of your choice that you can see within range perceives everything as hilariously funny and falls into fits of laughter if this spell affects it. The target must succeed on a Wisdom saving throw or fall prone, becoming incapacitated and unable to stand up for the duration. A creature with an Intelligence score of 4 or less isn't affected.\n\nAt the end of each of its turns, and each time it takes damage, the target can make another Wisdom saving throw. The target has advantage on the saving throw if it's triggered by damage. On a success, the spell ends.",
    "zh-CN": "施法距离内一个你选定且能看见的生物，会觉得一切都滑稽可笑；如果受到法术影响，它就会狂笑不止。目标必须成功通过一次感知豁免，否则倒地、陷入失能，并在法术持续时间内无法站起。智力为 4 或更低的生物不受影响。\n\n目标在自己的每个回合结束时，以及每次受到伤害时，都可以再次进行感知豁免。如果豁免由伤害触发，该次豁免具有优势。豁免成功时，法术结束。"
  },
  "spellHelp.native.hunter's-mark": {
    "en": "You choose a creature you can see within range and mystically mark it as your quarry. Until the spell ends, you deal an extra 1d6 damage to the target whenever you hit it with a weapon attack, and you have advantage on any Wisdom (Perception) or Wisdom (Survival) check you make to find it. If the target drops to 0 hit points before this spell ends, you can use a bonus action on a subsequent turn of yours to mark a new creature.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd or 4th level, you can maintain your concentration on the spell for up to 8 hours. When you use a spell slot of 5th level or higher, you can maintain your concentration on the spell for up to 24 hours.",
    "zh-CN": "你选择施法距离内一个能看见的生物，用魔法将它标记为猎物。法术结束前，你每次用武器攻击命中目标，都会额外造成 1d6 点伤害；为寻找目标而进行的感知（察觉）或感知（求生）检定也具有优势。如果目标在法术结束前生命值降至 0，你可以在之后自己的某个回合用一个附赠动作，标记一个新的生物。\n\n**升环施法。** 使用三环或四环法术位施放此法术时，你可以维持专注至多 8 小时。使用五环或更高环阶的法术位时，你可以维持专注至多 24 小时。"
  },
  "spellHelp.native.identify": {
    "en": "You choose one object that you must touch throughout the casting of the spell. If it is a magic item or some other magic-imbued object, you learn its properties and how to use them, whether it requires attunement to use, and how many charges it has, if any. You learn whether any spells are affecting the item and what they are. If the item was created by a spell, you learn which spell created it.\n\nIf you instead touch a creature throughout the casting, you learn what spells, if any, are currently affecting it.",
    "zh-CN": "你选择一个物体，并在整个施法过程中保持触碰它。如果它是魔法物品或其他蕴含魔法的物体，你会得知它的属性和使用方式、使用时是否需要同调，以及它拥有多少充能（如果有）。你会得知它是否正受到任何法术影响，以及这些法术是什么。如果物体由法术创造，你也会得知创造它的法术。\n\n如果你在整个施法过程中触碰的是一个生物，则会得知它当前受到哪些法术影响（如果有）。"
  },
  "spellHelp.native.illusory-script": {
    "en": "You write on parchment, paper, or some other suitable writing material and imbue it with a potent illusion that lasts for the duration.\n\nTo you and any creatures you designate when you cast the spell, the writing appears normal, written in your hand, and conveys whatever meaning you intended when you wrote the text. To all others, the writing appears as if it were written in an unknown or magical script that is unintelligible. Alternatively, you can cause the writing to appear to be an entirely different message, written in a different hand and language, though the language must be one you know.\n\nShould the spell be dispelled, the original script and the illusion both disappear.\n\nA creature with truesight can read the hidden message.",
    "zh-CN": "你在羊皮纸、纸张或其他适合书写的材料上写下文字，并为其注入强大的幻象，在法术持续时间内有效。\n\n对你以及施法时指定的生物而言，文字呈现正常，是你的笔迹，并表达你书写时想要传达的意思。对其他生物而言，文字看起来像是无法理解的未知文字或魔法文字。你也可以让它呈现为完全不同的讯息，采用不同的笔迹和语言，但该语言必须是你掌握的。\n\n如果法术被解除，原本的文字和幻象都会消失。\n\n拥有真实视觉的生物可以阅读隐藏的讯息。"
  },
  "spellHelp.native.inflict-wounds": {
    "en": "Make a melee spell attack against a creature you can reach. On a hit, the target takes 3d10 necrotic damage.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d10 for each slot level above 1st.",
    "zh-CN": "对一个你能触及的生物进行一次近战法术攻击。命中时，目标受到 3d10 点黯蚀伤害。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，伤害便增加 1d10。"
  },
  "spellHelp.native.jump": {
    "en": "You touch a creature. The creature's jump distance is tripled until the spell ends.",
    "zh-CN": "你触碰一个生物。法术结束前，该生物的跳跃距离变为原来的 3 倍。"
  },
  "spellHelp.native.longstrider": {
    "en": "You touch a creature. The target's speed increases by 10 feet until the spell ends.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st.",
    "zh-CN": "你触碰一个生物。法术结束前，目标的速度增加 10 英尺。\n\n**升环施法。** 当你使用二环或更高环阶的法术位施放此法术时，法术位每比一环高一环，就能额外指定一个目标。"
  },
  "spellHelp.native.protection-from-evil-and-good": {
    "en": "Until the spell ends, one willing creature you touch is protected against certain types of creatures: aberrations, celestials, elementals, fey, fiends, and undead.\n\nThe protection grants several benefits. Creatures of those types have disadvantage on attack rolls against the target. The target also can't be charmed, frightened, or possessed by them. If the target is already charmed, frightened, or possessed by such a creature, the target has advantage on any new saving throw against the relevant effect.",
    "zh-CN": "法术结束前，你触碰的一个自愿接受法术的生物，会获得针对以下生物类型的防护：异怪、天界生物、元素生物、精类、邪魔和不死生物。\n\n防护带来多项好处。这些类型的生物对目标进行攻击检定时具有劣势。目标也不能被它们魅惑、恐慌或附身。如果目标已经被这类生物魅惑、恐慌或附身，针对相关效果进行新的豁免时具有优势。"
  },
  "spellHelp.native.purify-food-and-drink": {
    "en": "All nonmagical food and drink within a 5-foot radius sphere centered on a point of your choice within range is purified and rendered free of poison and disease.",
    "zh-CN": "以施法距离内你选定的一点为中心，半径 5 英尺球形区域内的所有非魔法食物和饮料都会被净化，去除其中的毒素和疾病。"
  },
  "spellHelp.native.sanctuary": {
    "en": "You ward a creature within range against attack. Until the spell ends, any creature who targets the warded creature with an attack or a harmful spell must first make a Wisdom saving throw. On a failed save, the creature must choose a new target or lose the attack or spell. This spell doesn't protect the warded creature from area effects, such as the explosion of a fireball.\n\nIf the warded creature makes an attack, casts a spell that affects an enemy, or deals damage to another creature, this spell ends.",
    "zh-CN": "你保护施法距离内的一个生物，使其免受攻击。法术结束前，任何生物若想以攻击或有害法术指定受保护生物为目标，都必须先进行一次感知豁免。豁免失败时，攻击者必须选择一个新目标，否则失去此次攻击或法术。此法术不能保护目标免受区域效果影响，例如火球爆炸。\n\n如果受保护生物进行攻击、施放影响敌人的法术，或对其他生物造成伤害，此法术结束。"
  },
  "spellHelp.native.shield-of-faith": {
    "en": "A shimmering field appears and surrounds a creature of your choice within range, granting it a +2 bonus to AC for the duration.",
    "zh-CN": "一片闪烁的力场出现在施法距离内，环绕你选定的一个生物。法术持续时间内，该生物的护甲等级获得 +2 加值。"
  },
  "spellHelp.native.speak-with-animals": {
    "en": "You gain the ability to comprehend and verbally communicate with beasts for the duration. The knowledge and awareness of many beasts is limited by their intelligence, but at minimum, beasts can give you information about nearby locations and monsters, including whatever they can perceive or have perceived within the past day. You might be able to persuade a beast to perform a small favor for you, at the GM's discretion.",
    "zh-CN": "在法术持续时间内，你能理解野兽，并与它们进行口头交流。许多野兽的知识和认知受智力限制，但它们至少能告诉你附近地点和怪物的信息，包括当前能够感知或过去一天内曾感知到的事物。你可能说服野兽帮你一个小忙，具体由 DM 裁定。"
  },
  "spellHelp.native.unseen-servant": {
    "en": "This spell creates an invisible, mindless, shapeless, Medium force that performs simple tasks at your command until the spell ends. The servant springs into existence in an unoccupied space on the ground within range. It has AC 10, 1 hit point, and a Strength of 2, and it can't attack. If it drops to 0 hit points, the spell ends.\n\nOnce on each of your turns as a bonus action, you can mentally command the servant to move up to 15 feet and interact with an object. The servant can perform simple tasks that a human servant could do, such as fetching things, cleaning, mending, folding clothes, lighting fires, serving food, and pouring wine. Once you give the command, the servant performs the task to the best of its ability until it completes the task, then waits for your next command.\n\nIf you command the servant to perform a task that would move it more than 60 feet away from you, the spell ends.",
    "zh-CN": "此法术创造一股隐形、无心智、无形状的中型力量，直到法术结束前，都能按你的命令执行简单任务。仆役出现在施法距离内地面上一个未被占据的位置。它的护甲等级为 10、生命值为 1、力量为 2，且不能攻击。生命值降至 0 时，法术结束。\n\n在你的每个回合，你可以用一个附赠动作，以心灵命令仆役移动至多 15 英尺并操作一个物体，每回合限一次。仆役可以执行人类仆役能做的简单任务，例如取物、清洁、修补、叠衣、点火、端上食物和倒酒。收到命令后，仆役会尽力完成任务，然后等待下一条命令。\n\n如果你命令仆役执行的任务会使其离你超过 60 英尺，法术结束。"
  },
  "spellHelp.native.aid": {
    "en": "Your spell bolsters your allies with toughness and resolve. Choose up to three creatures within range. Each target's hit point maximum and current hit points increase by 5 for the duration.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, a target's hit points increase by an additional 5 for each slot level above 2nd.",
    "zh-CN": "此法术使你的盟友更加坚韧、坚定。选择施法距离内至多 3 个生物。在法术持续时间内，每个目标的生命值上限和当前生命值都增加 5。\n\n**升环施法。** 当你使用三环或更高环阶的法术位施放此法术时，法术位每比二环高一环，目标的生命值便额外增加 5。"
  },
  "spellHelp.native.barkskin": {
    "en": "You touch a willing creature. Until the spell ends, the target's skin has a rough, bark-like appearance, and the target's AC can't be less than 16, regardless of what kind of armor it is wearing.",
    "zh-CN": "你触碰一个自愿接受法术的生物。法术结束前，目标的皮肤呈现粗糙的树皮外观；无论穿着何种护甲，其护甲等级都不会低于 16。"
  },
  "spellHelp.native.blur": {
    "en": "Your body becomes blurred, shifting and wavering to all who can see you. For the duration, any creature has disadvantage on attack rolls against you. An attacker is immune to this effect if it doesn't rely on sight, as with blindsight, or can see through illusions, as with truesight.",
    "zh-CN": "在所有能看见你的人眼中，你的身体变得模糊、摇曳、不断变化。法术持续时间内，任何生物对你的攻击检定都具有劣势。如果攻击者不依赖视觉，例如拥有盲视，或能看穿幻象，例如拥有真实视觉，则不受此效果影响。"
  },
  "spellHelp.native.darkvision": {
    "en": "You touch a willing creature to grant it the ability to see in the dark. For the duration, that creature has darkvision out to a range of 60 feet.",
    "zh-CN": "你触碰一个自愿接受法术的生物，赋予它在黑暗中视物的能力。在法术持续时间内，该生物获得 60 英尺范围的黑暗视觉。"
  },
  "spellHelp.native.hold-person": {
    "en": "Choose a humanoid that you can see within range. The target must succeed on a Wisdom saving throw or be paralyzed for the duration. At the end of each of its turns, the target can make another Wisdom saving throw. On a success, the spell ends on the target.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, you can target one additional humanoid for each slot level above 2nd. The humanoids must be within 30 feet of each other when you target them.",
    "zh-CN": "选择施法距离内一个能看见的类人生物。目标必须成功通过一次感知豁免，否则在法术持续时间内麻痹。在它的每个回合结束时，目标都可以再次进行感知豁免；成功时，法术对该目标结束。\n\n**升环施法。** 当你使用三环或更高环阶的法术位施放此法术时，法术位每比二环高一环，就能额外指定一个类人生物。指定目标时，这些类人生物彼此之间的距离必须在 30 英尺以内。"
  },
  "spellHelp.native.invisibility": {
    "en": "A creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target's person. The spell ends for a target that attacks or casts a spell.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd.",
    "zh-CN": "你触碰的一个生物变为隐形，直到法术结束。目标穿戴或携带的物品只要仍在其身上，也会隐形。目标进行攻击或施放法术时，此法术对它结束。\n\n**升环施法。** 当你使用三环或更高环阶的法术位施放此法术时，法术位每比二环高一环，就能额外指定一个目标。"
  },
  "spellHelp.native.knock": {
    "en": "Choose an object that you can see within range. The object can be a door, a box, a chest, a set of manacles, a padlock, or another object that contains a mundane or magical means that prevents access.\n\nA target that is held shut by a mundane lock or that is stuck or barred becomes unlocked, unstuck, or unbarred. If the object has multiple locks, only one of them is unlocked.\n\nIf you choose a target that is held shut with *arcane lock*, that spell is suppressed for 10 minutes, during which time the target can be opened and shut normally.\n\nWhen you cast the spell, a loud knock, audible from as far away as 300 feet, emanates from the target object.",
    "zh-CN": "选择施法距离内一个能看见的物体。它可以是门、盒子、箱子、镣铐、挂锁，或其他以普通或魔法方式阻止开启或进入的物体。\n\n被普通锁锁住、卡住或被门闩闩住的目标，会被解锁、解除卡阻或打开门闩。如果物体有多个锁，只会打开其中一个。\n\n如果目标被*秘法锁*锁住，该法术会被压制 10 分钟；期间目标可以正常开启和关闭。\n\n施放此法术时，目标物体会发出响亮的敲击声，在 300 英尺外都能听见。"
  },
  "spellHelp.native.lesser-restoration": {
    "en": "You touch a creature and can end either one disease or one condition afflicting it. The condition can be blinded, deafened, paralyzed, or poisoned.",
    "zh-CN": "你触碰一个生物，可以结束影响它的一种疾病或一种状态。可结束的状态包括目盲、耳聋、麻痹或中毒。"
  },
  "spellHelp.native.magic-weapon": {
    "en": "You touch a nonmagical weapon. Until the spell ends, that weapon becomes a magic weapon with a +1 bonus to attack rolls and damage rolls.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the bonus increases to +2. When you use a spell slot of 6th level or higher, the bonus increases to +3.",
    "zh-CN": "你触碰一件非魔法武器。法术结束前，它变为魔法武器，攻击检定和伤害掷骰获得 +1 加值。\n\n**升环施法。** 使用四环或更高环阶的法术位施放此法术时，加值增加至 +2。使用六环或更高环阶的法术位时，加值增加至 +3。"
  },
  "spellHelp.native.mirror-image": {
    "en": "Three illusory duplicates of yourself appear in your space. Until the spell ends, the duplicates move with you and mimic your actions, shifting position so it's impossible to track which image is real. You can use your action to dismiss the illusory duplicates.\n\nEach time a creature targets you with an attack during the spell's duration, roll a d20 to determine whether the attack instead targets one of your duplicates.\n\nIf you have three duplicates, you must roll a 6 or higher to change the attack's target to a duplicate. With two duplicates, you must roll an 8 or higher. With one duplicate, you must roll an 11 or higher.\n\nA duplicate's AC equals 10 + your Dexterity modifier. If an attack hits a duplicate, the duplicate is destroyed. A duplicate can be destroyed only by an attack that hits it. It ignores all other damage and effects. The spell ends when all three duplicates are destroyed.\n\nA creature is unaffected by this spell if it can't see, if it relies on senses other than sight, such as blindsight, or if it can perceive illusions as false, as with truesight.",
    "zh-CN": "你的所在位置出现 3 个幻象分身。法术结束前，分身随你移动并模仿你的动作，不断变换位置，使人无法分辨哪个是真身。你可以用一个动作解除这些幻象分身。\n\n法术持续时间内，每当一个生物以攻击指定你为目标时，掷 1d20，决定攻击是否转而指定一个分身。\n\n有 3 个分身时，掷出 6 或更高即可将攻击目标改为分身；有 2 个分身时，需要 8 或更高；有 1 个分身时，需要 11 或更高。\n\n分身的护甲等级等于 10 + 你的敏捷调整值。攻击命中分身时，分身被摧毁。只有命中分身的攻击才能摧毁它；分身忽略所有其他伤害和效果。全部 3 个分身被摧毁时，法术结束。\n\n如果一个生物看不见、依赖视觉以外的感官（例如盲视），或能看穿幻象（例如拥有真实视觉），则不受此法术影响。"
  },
  "spellHelp.native.misty-step": {
    "en": "Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space that you can see.",
    "zh-CN": "银色薄雾短暂环绕着你。你传送至多 30 英尺，到达一个你能看见且未被占据的位置。"
  },
  "spellHelp.native.pass-without-trace": {
    "en": "A veil of shadows and silence radiates from you, masking you and your companions from detection. For the duration, each creature you choose within 30 feet of you (including you) has a +10 bonus to Dexterity (Stealth) checks and can't be tracked except by magical means. A creature that receives this bonus leaves behind no tracks or other traces of its passage.",
    "zh-CN": "一层阴影与寂静从你身上扩散，遮掩你和同伴，使你们不易被发现。在法术持续时间内，你周围 30 英尺内由你选定的每个生物（可以包括你自己），其敏捷（隐匿）检定获得 +10 加值，且除魔法手段外无法被追踪。获得此加值的生物不会留下足迹或其他经过的痕迹。"
  },
  "spellHelp.native.prayer-of-healing": {
    "en": "Up to six creatures of your choice that you can see within range each regain hit points equal to 2d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, the healing increases by 1d8 for each slot level above 2nd.",
    "zh-CN": "施法距离内至多 6 个你选定且能看见的生物，各自恢复生命值，数值等于 2d8 + 你的施法属性调整值。此法术对不死生物和构装体无效。\n\n**升环施法。** 当你使用三环或更高环阶的法术位施放此法术时，法术位每比二环高一环，治疗量便增加 1d8。"
  },
  "spellHelp.native.protection-from-poison": {
    "en": "You touch a creature. If it is poisoned, you neutralize the poison. If more than one poison afflicts the target, you neutralize one poison that you know is present, or you neutralize one at random.\n\nFor the duration, the target has advantage on saving throws against being poisoned, and it has resistance to poison damage.",
    "zh-CN": "你触碰一个生物。如果它已中毒，你会中和毒素。如果目标受到多种毒素影响，你会中和其中一种已知存在的毒素，或随机中和一种。\n\n在法术持续时间内，目标针对中毒进行的豁免具有优势，并获得毒素伤害抗性。"
  },
  "spellHelp.native.scorching-ray": {
    "en": "You create three rays of fire and hurl them at targets within range. You can hurl them at one target or several.\n\nMake a ranged spell attack for each ray. On a hit, the target takes 2d6 fire damage.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, you create one additional ray for each slot level above 2nd.",
    "zh-CN": "你创造 3 道火焰射线，射向施法距离内的目标。可以让它们攻击同一目标，也可以分配给多个目标。\n\n每道射线分别进行一次远程法术攻击。命中时，目标受到 2d6 点火焰伤害。\n\n**升环施法。** 当你使用三环或更高环阶的法术位施放此法术时，法术位每比二环高一环，便额外产生一道射线。"
  },
  "spellHelp.native.see-invisibility": {
    "en": "For the duration, you see invisible creatures and objects as if they were visible, and you can see into the Ethereal Plane. Ethereal creatures and objects appear ghostly and translucent.",
    "zh-CN": "在法术持续时间内，你能看见隐形生物和物体，如同它们没有隐形，也能看进以太位面。以太生物和物体呈现为幽灵般的半透明形态。"
  },
  "spellHelp.native.shatter": {
    "en": "A sudden loud ringing noise, painfully intense, erupts from a point of your choice within range. Each creature in a 10-foot radius sphere centered on that point must make a Constitution saving throw. A creature takes 3d8 thunder damage on a failed save, or half as much damage on a successful one. A creature made of inorganic material such as stone, crystal, or metal has disadvantage on this saving throw.\n\nA nonmagical object that isn't being worn or carried also takes the damage if it's in the spell's area.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd.",
    "zh-CN": "施法距离内你选定的一点骤然爆发出剧烈刺耳的鸣响。以该点为中心，半径 10 英尺球形区域内的每个生物都必须进行体质豁免。豁免失败时，生物受到 3d8 点雷鸣伤害；豁免成功则受到一半伤害。由石头、水晶、金属等无机材料构成的生物，在这次豁免中具有劣势。\n\n区域内未被穿戴或携带的非魔法物体也会受到此伤害。\n\n**升环施法。** 当你使用三环或更高环阶的法术位施放此法术时，法术位每比二环高一环，伤害便增加 1d8。"
  },
  "spellHelp.native.silence": {
    "en": "For the duration, no sound can be created within or pass through a 20-foot radius sphere centered on a point you choose within range. Any creature or object entirely inside the sphere is immune to thunder damage, and creatures are deafened while entirely inside it. Casting a spell that includes a verbal component is impossible there.",
    "zh-CN": "在法术持续时间内，以施法距离内你选定的一点为中心，半径 20 英尺的球形区域内无法产生声音，声音也无法穿过该区域。完全位于球体内的生物或物体免疫雷鸣伤害；完全位于其中的生物处于耳聋状态。在区域内无法施放包含言语成分的法术。"
  },
  "spellHelp.native.spider-climb": {
    "en": "Until the spell ends, one willing creature you touch gains the ability to move up, down, and across vertical surfaces and upside down along ceilings, while leaving its hands free. The target also gains a climbing speed equal to its walking speed.",
    "zh-CN": "法术结束前，你触碰的一个自愿接受法术的生物，可以沿垂直表面向上、向下或横向移动，也能倒挂着沿天花板移动，同时双手保持空闲。目标还获得等于其步行速度的攀爬速度。"
  },
  "spellHelp.native.spiritual-weapon": {
    "en": "You create a floating, spectral weapon within range that lasts for the duration or until you cast this spell again. When you cast the spell, you can make a melee spell attack against a creature within 5 feet of the weapon. On a hit, the target takes force damage equal to 1d8 + your spellcasting ability modifier.\n\nAs a bonus action on your turn, you can move the weapon up to 20 feet and repeat the attack against a creature within 5 feet of it.\n\nThe weapon can take whatever form you choose. Clerics of deities who are associated with a particular weapon (as St. Cuthbert is known for his mace and Thor for his hammer) make this spell's effect resemble that weapon.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for every two slot levels above 2nd.",
    "zh-CN": "你在施法距离内创造一件漂浮的幽灵武器，在法术持续时间内存在，或直到你再次施放此法术。施法时，你可以对武器周围 5 英尺内的一个生物进行一次近战法术攻击。命中时，目标受到力场伤害，数值等于 1d8 + 你的施法属性调整值。\n\n在你的回合，你可以用一个附赠动作，将武器移动至多 20 英尺，并对武器周围 5 英尺内的一个生物再次进行攻击。\n\n武器可以采用你选择的任意形态。如果牧师信奉的神祇与某种武器有关，例如圣库斯伯特的硬头锤或托尔的战锤，通常会使法术显现为该武器的形态。\n\n**升环施法。** 当你使用三环或更高环阶的法术位施放此法术时，法术位每比二环高两环，伤害便增加 1d8。"
  },
  "spellHelp.native.acid-arrow": {
    "en": "A shimmering green arrow streaks toward a target within range and bursts in a spray of acid. Make a ranged spell attack against the target. On a hit, the target takes 4d4 acid damage immediately and 2d4 acid damage at the end of its next turn. On a miss, the arrow splashes the target with acid for half as much of the initial damage and no damage at the end of its next turn.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, the damage (both initial and later) increases by 1d4 for each slot level above 2nd.",
    "zh-CN": "一支闪烁的绿色箭矢射向施法距离内的目标，炸成一片酸液。对目标进行一次远程法术攻击。命中时，目标立刻受到 4d4 点强酸伤害，并在其下一回合结束时再受到 2d4 点强酸伤害。未命中时，箭矢溅出的酸液仍对目标造成初始伤害的一半，但不会在其下一回合结束时造成伤害。\n\n**升环施法。** 当你使用三环或更高环阶的法术位施放此法术时，法术位每比二环高一环，初始伤害和后续伤害各增加 1d4。"
  },
  "spellHelp.native.alter-self": {
    "en": "You assume a different form. When you cast the spell, choose one of the following options, the effects of which last for the duration of the spell. While the spell lasts, you can end one option as an action to gain the benefits of a different one.\n\n***Aquatic Adaptation***. You adapt your body to an aquatic environment, sprouting gills and growing webbing between your fingers. You can breathe underwater and gain a swimming speed equal to your walking speed.\n\n***Change Appearance***. You transform your appearance. You decide what you look like, including your height, weight, facial features, sound of your voice, hair length, coloration, and distinguishing characteristics, if any. You can make yourself appear as a member of another race, though none of your statistics change. You also can't appear as a creature of a different size than you, and your basic shape stays the same; if you're bipedal, you can't use this spell to become quadrupedal, for instance. At any time for the duration of the spell, you can use your action to change your appearance in this way again.\n\n***Natural Weapons***. You grow claws, fangs, spines, horns, or a different natural weapon of your choice. Your unarmed strikes deal 1d6 bludgeoning, piercing, or slashing damage, as appropriate to the natural weapon you chose, and you are proficient with your unarmed strikes. Finally, the natural weapon is magic and you have a +1 bonus to the attack and damage rolls you make using it.",
    "zh-CN": "你采用不同的形态。施法时选择以下一个选项，其效果在法术持续时间内有效。法术持续期间，你可以用一个动作结束当前选项，转而获得另一个选项的好处。\n\n***适应水域。*** 你的身体适应水生环境，长出鳃，手指之间生出蹼。你可以在水下呼吸，并获得等于步行速度的游泳速度。\n\n***改变外貌。*** 你改变自己的外观，决定身高、体重、面部特征、声音、头发长度、肤色及显著特征等。你可以看起来像另一个种族的成员，但任何数据都不会改变。你不能呈现为与自己体型不同的生物，基本身体结构也保持不变；例如，两足生物不能借此变成四足生物。法术持续期间，你随时可以用一个动作再次以此方式改变外貌。\n\n***天生武器。*** 你长出爪、獠牙、尖刺、角或其他自选的天生武器。徒手打击造成 1d6 点钝击、穿刺或挥砍伤害，伤害类型取决于所选天生武器，并且你具有徒手打击熟练。此外，这件天生武器具有魔法，使用它进行的攻击检定和伤害掷骰获得 +1 加值。"
  },
  "spellHelp.native.animal-messenger": {
    "en": "By means of this spell, you use an animal to deliver a message. Choose a Tiny beast you can see within range, such as a squirrel, a blue jay, or a bat. You specify a location, which you must have visited, and a recipient who matches a general description, such as \"a man or woman dressed in the uniform of the town guard\" or \"a red-haired dwarf wearing a pointed hat.\" You also speak a message of up to twenty-five words. The target beast travels for the duration of the spell toward the specified location, covering about 50 miles per 24 hours for a flying messenger, or 25 miles for other animals.\n\nWhen the messenger arrives, it delivers your message to the creature that you described, replicating the sound of your voice. The messenger speaks only to a creature matching the description you gave. If the messenger doesn't reach its destination before the spell ends, the message is lost, and the beast makes its way back to where you cast this spell.\n\n**At Higher Levels.** If you cast this spell using a spell slot of 3nd level or higher, the duration of the spell increases by 48 hours for each slot level above 2nd.",
    "zh-CN": "你借助一个动物传递讯息。选择施法距离内一个能看见的微型野兽，例如松鼠、蓝松鸦或蝙蝠。指定一个你曾到过的地点，以及符合大致描述的收件人，例如“穿着城镇卫兵制服的男子或女子”，或“戴着尖顶帽的红发矮人”。你还需说出一条不超过 25 个词的讯息。目标野兽在法术持续时间内前往指定地点：飞行动物每 24 小时约行进 50 英里，其他动物约行进 25 英里。\n\n信使抵达后，会模仿你的声音，将讯息传达给你描述的生物。它只会对符合描述的生物说话。如果法术结束前未能抵达目的地，讯息便会丢失，野兽会返回你施法的位置。\n\n**升环施法。** 使用三环或更高环阶的法术位施放此法术时，法术位每比二环高一环，持续时间便增加 48 小时。"
  },
  "spellHelp.native.arcane-lock": {
    "en": "You touch a closed door, window, gate, chest, or other entryway, and it becomes locked for the duration. You and the creatures you designate when you cast this spell can open the object normally. You can also set a password that, when spoken within 5 feet of the object, suppresses this spell for 1 minute. Otherwise, it is impassable until it is broken or the spell is dispelled or suppressed. Casting *knock* on the object suppresses *arcane lock* for 10 minutes.\n\nWhile affected by this spell, the object is more difficult to break or force open; the DC to break it or pick any locks on it increases by 10.",
    "zh-CN": "你触碰一扇关闭的门、窗、大门、箱子或其他入口，使其在法术持续时间内上锁。你以及施法时指定的生物可以正常打开它。你也可以设置一个口令；在物体周围 5 英尺内说出口令，便会压制法术 1 分钟。除此之外，除非将其破坏，或法术被解除或压制，否则无法通过。对物体施放*敲击术*会压制*秘法锁* 10 分钟。\n\n受此法术影响的物体更难破坏或强行打开；破坏它或撬开其上任何锁的 DC 增加 10。"
  },
  "spellHelp.native.arcanist's-magic-aura": {
    "en": "You place an illusion on a creature or an object you touch so that divination spells reveal false information about it. The target can be a willing creature or an object that isn't being carried or worn by another creature.\n\nWhen you cast the spell, choose one or both of the following effects. The effect lasts for the duration. If you cast this spell on the same creature or object every day for 30 days, placing the same effect on it each time, the illusion lasts until it is dispelled.\n\n***False Aura***. You change the way the target appears to spells and magical effects, such as *detect magic*, that detect magical auras. You can make a nonmagical object appear magical, a magical object appear nonmagical, or change the object's magical aura so that it appears to belong to a specific school of magic that you choose. When you use this effect on an object, you can make the false magic apparent to any creature that handles the item.\n\n***Mask***. You change the way the target appears to spells and magical effects that detect creature types, such as a paladin's Divine Sense or the trigger of a *symbol* spell. You choose a creature type and other spells and magical effects treat the target as if it were a creature of that type or of that alignment.",
    "zh-CN": "你对触碰的一个生物或物体施加幻象，使预言法术获知关于它的虚假信息。目标可以是自愿接受法术的生物，或未被其他生物穿戴或携带的物体。\n\n施法时，选择以下一种或两种效果，在法术持续时间内有效。如果连续 30 天每天都对同一个生物或物体施放此法术，并施加相同效果，幻象便会持续到被解除为止。\n\n***虚假灵光。*** 你改变目标在侦测魔法灵光的法术和魔法效果中呈现的样子，例如*侦测魔法*。你可以使非魔法物体看起来具有魔法，使魔法物体看起来没有魔法，或改变物体的魔法灵光，使其看起来属于你选定的魔法学派。对物体使用此效果时，你可以让任何拿起它的生物都能察觉到这份虚假的魔法。\n\n***伪装。*** 你改变目标在侦测生物类型的法术和魔法效果中呈现的样子，例如圣武士的神圣感知或*徽记术*的触发条件。你选择一个生物类型，其他法术和魔法效果便会将目标视为该类型或该阵营的生物。"
  },
  "spellHelp.native.augury": {
    "en": "By casting gem-inlaid sticks, rolling dragon bones, laying out ornate cards, or employing some other divining tool, you receive an omen from an otherworldly entity about the results of a specific course of action that you plan to take within the next 30 minutes. The GM chooses from the following possible omens:\n\n- *Weal*, for good results\n- *Woe*, for bad results\n- *Weal and woe*, for both good and bad results\n- *Nothing*, for results that aren't especially good or bad\n\nThe spell doesn't take into account any possible circumstances that might change the outcome, such as the casting of additional spells or the loss or gain of a companion.\n\nIf you cast the spell two or more times before completing your next long rest, there is a cumulative 25 percent chance for each casting after the first that you get a random reading. The GM makes this roll in secret.",
    "zh-CN": "通过抛掷镶嵌宝石的木签、滚动龙骨、排列华丽卡牌或使用其他占卜工具，你从异界存在那里获得预兆，了解你计划在未来 30 分钟内采取的某项行动可能带来的结果。DM 从以下预兆中选择：\n\n- *吉*：结果有利。\n- *凶*：结果不利。\n- *吉凶并存*：既有利也有弊。\n- *无兆*：结果没有特别的好坏。\n\n此法术不会考虑可能改变结果的其他情况，例如额外施放法术，或失去、增加一个同伴。\n\n在完成下一次长休前，如果你施放此法术两次或更多次，从第二次开始，每次施法获得随机占卜结果的概率累计增加 25%。这次掷骰由 DM 秘密进行。"
  },
  "spellHelp.native.blindness/deafness": {
    "en": "You can blind or deafen a foe. Choose one creature that you can see within range to make a Constitution saving throw. If it fails, the target is either blinded or deafened (your choice) for the duration. At the end of each of its turns, the target can make a Constitution saving throw. On a success, the spell ends.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd.",
    "zh-CN": "你可以使一个敌人目盲或耳聋。选择施法距离内一个能看见的生物，令其进行体质豁免。豁免失败时，目标在法术持续时间内目盲或耳聋，由你选择。在它的每个回合结束时，目标都可以再次进行体质豁免；成功时，法术结束。\n\n**升环施法。** 当你使用三环或更高环阶的法术位施放此法术时，法术位每比二环高一环，就能额外指定一个目标。"
  },
  "spellHelp.native.branding-smite": {
    "en": "The next time you hit a creature with a weapon attack before this spell ends, the weapon gleams with astral radiance as you strike. The attack deals an extra 2d6 radiant damage to the target, which becomes visible if it's invisible, and the target sheds dim light in a 5-foot radius and can't become invisible until the spell ends.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, the extra damage increases by 1d6 for each slot level above 2nd.",
    "zh-CN": "法术结束前，你下一次用武器攻击命中一个生物时，武器在击中瞬间闪耀星界光辉。该攻击额外对目标造成 2d6 点光耀伤害；隐形目标会显形，目标在周围 5 英尺半径内发出微光，并在法术结束前无法变为隐形。\n\n**升环施法。** 当你使用三环或更高环阶的法术位施放此法术时，法术位每比二环高一环，额外伤害便增加 1d6。"
  },
  "spellHelp.native.calm-emotions": {
    "en": "You attempt to suppress strong emotions in a group of people. Each humanoid in a 20-foot radius sphere centered on a point you choose within range must make a Charisma saving throw; a creature can choose to fail this saving throw if it wishes. If a creature fails its saving throw, choose one of the following two effects.\n\nYou can suppress any effect causing a target to be charmed or frightened. When this spell ends, any suppressed effect resumes, provided that its duration has not expired in the meantime.\n\nAlternatively, you can make a target indifferent about creatures of your choice that it is hostile toward. This indifference ends if the target is attacked or harmed by a spell or if it witnesses any of its friends being harmed. When the spell ends, the creature becomes hostile again, unless the GM rules otherwise.",
    "zh-CN": "你试图压制一群人的强烈情绪。以施法距离内你选定的一点为中心，半径 20 英尺球形区域内的每个类人生物都必须进行魅力豁免；生物可以自愿选择豁免失败。如果一个生物豁免失败，选择以下两种效果之一。\n\n你可以压制任何使目标魅惑或恐慌的效果。法术结束时，只要被压制效果的持续时间尚未结束，它就会恢复。\n\n也可以让目标对你选定且原本敌视的生物暂时漠不关心。如果目标受到攻击、被法术伤害，或目睹自己的朋友受伤，这种漠然便会结束。法术结束时，目标重新变得敌对，除非 DM 另有裁定。"
  },
  "spellHelp.native.continual-flame": {
    "en": "A flame, equivalent in brightness to a torch, springs forth from an object that you touch. The effect looks like a regular flame, but it creates no heat and doesn't use oxygen. A *continual flame* can be covered or hidden but not smothered or quenched.",
    "zh-CN": "你触碰的物体上燃起一团亮度相当于火把的火焰。它看起来像普通火焰，但不产生热量，也不消耗氧气。*不灭明焰*可以被遮盖或隐藏，但不能被闷熄或扑灭。"
  },
  "spellHelp.native.darkness": {
    "en": "Magical darkness spreads from a point you choose within range to fill a 15-foot radius sphere for the duration. The darkness spreads around corners. A creature with darkvision can't see through this darkness, and nonmagical light can't illuminate it.\n\nIf the point you choose is on an object you are holding or one that isn't being worn or carried, the darkness emanates from the object and moves with it. Completely covering the source of the darkness with an opaque object, such as a bowl or a helm, blocks the darkness.\n\nIf any of this spell's area overlaps with an area of light created by a spell of 2nd level or lower, the spell that created the light is dispelled.",
    "zh-CN": "魔法黑暗从施法距离内你选定的一点扩散，在法术持续时间内充满半径 15 英尺的球形区域。黑暗会绕过转角扩散。黑暗视觉无法看穿这片黑暗，非魔法光照也无法照亮它。\n\n如果选定点位于你持握的物体上，或一个未被穿戴或携带的物体上，黑暗就会从该物体发出并随其移动。用碗、头盔等不透明物体完全盖住黑暗源头，可以阻挡黑暗。\n\n如果此法术的区域与二环或更低环阶法术创造的光照区域发生任何重叠，创造光照的法术会被解除。"
  },
  "spellHelp.native.find-traps": {
    "en": "You sense the presence of any trap within range that is within line of sight. A trap, for the purpose of this spell, includes anything that would inflict a sudden or unexpected effect you consider harmful or undesirable, which was specifically intended as such by its creator. Thus, the spell would sense an area affected by the *alarm* spell, a *glyph of warding*, or a mechanical pit trap, but it would not reveal a natural weakness in the floor, an unstable ceiling, or a hidden sinkhole.\n\nThis spell merely reveals that a trap is present.\n\nYou don't learn the location of each trap, but you do learn the general nature of the danger posed by a trap you sense.",
    "zh-CN": "你能感知施法距离内且位于视线范围内的陷阱是否存在。对于此法术，陷阱指的是其创造者特意设计、会产生你认为有害或不希望发生的突发效果的东西。因此，此法术可以感知受*警报术*影响的区域、*守卫刻文*或机械陷坑，但不会揭示地板的天然薄弱处、不稳的天花板或隐藏的天然塌陷坑。\n\n此法术只会告诉你存在陷阱。\n\n你不会得知每个陷阱的位置，但会了解所感知陷阱带来的危险的大致性质。"
  },
  "spellHelp.native.gentle-repose": {
    "en": "You touch a corpse or other remains. For the duration, the target is protected from decay and can't become undead.\n\nThe spell also effectively extends the time limit on raising the target from the dead, since days spent under the influence of this spell don't count against the time limit of spells such as *raise dead*.",
    "zh-CN": "你触碰一具尸体或其他遗骸。在法术持续时间内，目标不会腐烂，也不能变为不死生物。\n\n此法术还会有效延长复活目标的期限，因为受此法术影响的天数，不计入*死者复活*等法术的时限。"
  },
  "spellHelp.native.locate-animals-or-plants": {
    "en": "Describe or name a specific kind of beast or plant. Concentrating on the voice of nature in your surroundings, you learn the direction and distance to the closest creature or plant of that kind within 5 miles, if any are present.",
    "zh-CN": "描述或说出一种野兽或植物的名称。你专注聆听周围自然的声音，如果 5 英里内存在该类生物或植物，就能得知距离最近者的方向和距离。"
  },
  "spellHelp.native.locate-object": {
    "en": "Describe or name an object that is familiar to you. You sense the direction to the object's location, as long as that object is within 1,000 feet of you. If the object is in motion, you know the direction of its movement.\n\nThe spell can locate a specific object known to you, as long as you have seen it up close-within 30 feet-at least once. Alternatively, the spell can locate the nearest object of a particular kind, such as a certain kind of apparel, jewelry, furniture, tool, or weapon.\n\nThis spell can't locate an object if any thickness of lead, even a thin sheet, blocks a direct path between you and the object.",
    "zh-CN": "描述或说出一个你熟悉的物体的名称。只要它位于你周围 1,000 英尺内，你便能感知其所在方向。如果物体正在移动，你还会知道它的移动方向。\n\n此法术可以寻找你熟悉的某个特定物体，但你必须至少曾在 30 英尺以内近距离见过它一次。也可以寻找距离最近的某类物体，例如某种服装、珠宝、家具、工具或武器。\n\n如果你与物体之间的直线路径被任何厚度的铅阻挡，即使只是一层薄铅板，此法术也无法定位它。"
  },
  "spellHelp.native.ray-of-enfeeblement": {
    "en": "A black beam of enervating energy springs from your finger toward a creature within range. Make a ranged spell attack against the target. On a hit, the target deals only half damage with weapon attacks that use Strength until the spell ends.\n\nAt the end of each of the target's turns, it can make a Constitution saving throw against the spell. On a success, the spell ends.",
    "zh-CN": "一道削弱力量的黑色能量束从你的手指射向施法距离内的一个生物。对目标进行一次远程法术攻击。命中时，法术结束前，目标使用力量进行的武器攻击只造成一半伤害。\n\n在目标的每个回合结束时，它都可以针对法术进行体质豁免；成功时，法术结束。"
  },
  "spellHelp.native.detect-thoughts": {
    "en": "For the duration, you can read the thoughts of certain creatures. When you cast the spell and as your action on each turn until the spell ends, you can focus your mind on any one creature that you can see within 30 feet of you. If the creature you choose has an Intelligence of 3 or lower or doesn't speak any language, the creature is unaffected.\n\nYou initially learn the surface thoughts of the creature-what is most on its mind in that moment. As an action, you can either shift your attention to another creature's thoughts or attempt to probe deeper into the same creature's mind. If you probe deeper, the target must make a Wisdom saving throw. If it fails, you gain insight into its reasoning (if any), its emotional state, and something that looms large in its mind (such as something it worries over, loves, or hates). If it succeeds, the spell ends. Either way, the target knows that you are probing into its mind, and unless you shift your attention to another creature's thoughts, the creature can use its action on its turn to make an Intelligence check contested by your Intelligence check; if it succeeds, the spell ends.\n\nQuestions verbally directed at the target creature naturally shape the course of its thoughts, so this spell is particularly effective as part of an interrogation.\n\nYou can also use this spell to detect the presence of thinking creatures you can't see. When you cast the spell or as your action during the duration, you can search for thoughts within 30 feet of you. The spell can penetrate barriers, but 2 feet of rock, 2 inches of any metal other than lead, or a thin sheet of lead blocks you. You can't detect a creature with an Intelligence of 3 or lower or one that doesn't speak any language.\n\nOnce you detect the presence of a creature in this way, you can read its thoughts for the rest of the duration as described above, even if you can't see it, but it must still be within range.",
    "zh-CN": "在法术持续时间内，你能读取某些生物的思想。施法时，以及法术结束前每个回合用一个动作，你可以将注意力集中于周围 30 英尺内一个能看见的生物。如果目标智力为 3 或更低，或不会说任何语言，则不受影响。\n\n你最初获知目标的表层思想，也就是它此刻最在意的事。你可以用一个动作，将注意力转向另一个生物，或试图深入同一目标的内心。深入探查时，目标必须进行感知豁免。失败时，你会了解它的思考方式（如果有）、情绪状态，以及内心的重要事情，例如忧虑、喜爱或憎恨之事。成功时，法术结束。无论结果如何，目标都会知道你正探查它的思想；除非你将注意力转向其他生物，否则它可以在自己的回合用一个动作进行智力检定，与你的智力检定对抗；它获胜时，法术结束。\n\n向目标口头提问会自然引导它的思绪，因此此法术在审问时尤其有效。\n\n你也可以用此法术探测看不见但正在思考的生物。施法时，或在持续时间内用一个动作，你可以搜寻周围 30 英尺内的思想。法术能穿透障碍，但 2 英尺厚的岩石、2 英寸厚的非铅金属，或一层薄铅板会阻挡它。你不能探测智力为 3 或更低，或不会说任何语言的生物。\n\n以此方式探测到生物后，即使看不见它，你仍能在剩余持续时间内按上述方式读取其思想，但它必须保持在施法距离内。"
  },
  "spellHelp.native.enhance-ability": {
    "en": "You touch a creature and bestow upon it a magical enhancement. Choose one of the following effects; the target gains that effect until the spell ends.\n\n***Bear's Endurance***. The target has advantage on Constitution checks. It also gains 2d6 temporary hit points, which are lost when the spell ends.\n\n***Bull's Strength***. The target has advantage on Strength checks, and his or her carrying capacity doubles.\n\n***Cat's Grace***. The target has advantage on Dexterity checks. It also doesn't take damage from falling 20 feet or less if it isn't incapacitated.\n\n***Eagle's Splendor***. The target has advantage on Charisma checks.\n\n***Fox's Cunning***. The target has advantage on Intelligence checks.\n\n***Owl's Wisdom***. The target has advantage on Wisdom checks.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd.",
    "zh-CN": "你触碰一个生物，赋予它魔法强化。选择以下一种效果，目标在法术结束前获得该效果。\n\n***熊之坚韧。*** 目标的体质检定具有优势，并获得 2d6 点临时生命值，法术结束时这些临时生命值消失。\n\n***牛之力量。*** 目标的力量检定具有优势，负重能力翻倍。\n\n***猫之优雅。*** 目标的敏捷检定具有优势。只要未处于失能状态，它从不超过 20 英尺的高度坠落时不会受到伤害。\n\n***鹰之威仪。*** 目标的魅力检定具有优势。\n\n***狐之机敏。*** 目标的智力检定具有优势。\n\n***枭之睿智。*** 目标的感知检定具有优势。\n\n**升环施法。** 当你使用三环或更高环阶的法术位施放此法术时，法术位每比二环高一环，就能额外指定一个目标。"
  },
  "spellHelp.native.enlarge/reduce": {
    "en": "You cause a creature or an object you can see within range to grow larger or smaller for the duration. Choose either a creature or an object that is neither worn nor carried. If the target is unwilling, it can make a Constitution saving throw. On a success, the spell has no effect.\n\nIf the target is a creature, everything it is wearing and carrying changes size with it. Any item dropped by an affected creature returns to normal size at once.\n\n***Enlarge***. The target's size doubles in all dimensions, and its weight is multiplied by eight. This growth increases its size by one category- from Medium to Large, for example. If there isn't enough room for the target to double its size, the creature or object attains the maximum possible size in the space available. Until the spell ends, the target also has advantage on Strength checks and Strength saving throws. The target's weapons also grow to match its new size. While these weapons are enlarged, the target's attacks with them deal 1d4 extra damage.\n\n***Reduce***. The target's size is halved in all dimensions, and its weight is reduced to one-eighth of normal. This reduction decreases its size by one category-from Medium to Small, for example. Until the spell ends, the target also has disadvantage on Strength checks and Strength saving throws. The target's weapons also shrink to match its new size. While these weapons are reduced, the target's attacks with them deal 1d4 less damage (this can't reduce the damage below 1).",
    "zh-CN": "你使施法距离内一个能看见的生物或物体，在法术持续时间内变大或变小。目标可以是生物，或未被穿戴或携带的物体。如果目标不愿接受法术，可以进行体质豁免；成功时，法术无效。\n\n如果目标是生物，它穿戴或携带的一切都会随其改变大小。受影响生物丢下的物品会立刻恢复正常大小。\n\n***变大。*** 目标在各个方向上的尺寸翻倍，重量变为 8 倍，体型增大一级，例如从中型变为大型。如果空间不足以容纳翻倍后的目标，生物或物体会增大到现有空间允许的最大尺寸。法术结束前，目标的力量检定和力量豁免具有优势。目标的武器也随之变大；武器变大期间，目标使用它们进行的攻击额外造成 1d4 点伤害。\n\n***变小。*** 目标在各个方向上的尺寸减半，重量变为原来的八分之一，体型缩小一级，例如从中型变为小型。法术结束前，目标的力量检定和力量豁免具有劣势。目标的武器也随之缩小；武器缩小期间，目标使用它们进行的攻击伤害减少 1d4，但不能使伤害低于 1。"
  },
  "spellHelp.native.enthrall": {
    "en": "You weave a distracting string of words, causing creatures of your choice that you can see within range and that can hear you to make a Wisdom saving throw. Any creature that can't be charmed succeeds on this saving throw automatically, and if you or your companions are fighting a creature, it has advantage on the save. On a failed save, the target has disadvantage on Wisdom (Perception) checks made to perceive any creature other than you until the spell ends or until the target can no longer hear you. The spell ends if you are incapacitated or can no longer speak.",
    "zh-CN": "你编织一连串引人分心的话语，使施法距离内你选定、能看见且能听见你的生物进行感知豁免。不能被魅惑的生物自动成功。如果你或你的同伴正在与某个目标战斗，该目标的豁免具有优势。失败时，目标为察觉你以外的任何生物而进行的感知（察觉）检定具有劣势，直到法术结束或它无法再听见你。你失能或无法继续说话时，法术结束。"
  },
  "spellHelp.native.find-steed": {
    "en": "You summon a spirit that assumes the form of an unusually intelligent, strong, and loyal steed, creating a long-lasting bond with it. Appearing in an unoccupied space within range, the steed takes on a form that you choose: a warhorse, a pony, a camel, an elk, or a mastiff. (Your GM might allow other animals to be summoned as steeds.) The steed has the statistics of the chosen form, though it is a celestial, fey, or fiend (your choice) instead of its normal type. Additionally, if your steed has an Intelligence of 5 or less, its Intelligence becomes 6, and it gains the ability to understand one language of your choice that you speak.\n\nYour steed serves you as a mount, both in combat and out, and you have an instinctive bond with it that allows you to fight as a seamless unit. While mounted on your steed, you can make any spell you cast that targets only you also target your steed.\n\nWhen the steed drops to 0 hit points, it disappears, leaving behind no physical form. You can also dismiss your steed at any time as an action, causing it to disappear. In either case, casting this spell again summons the same steed, restored to its hit point maximum.\n\nWhile your steed is within 1 mile of you, you can communicate with each other telepathically.\n\nYou can't have more than one steed bonded by this spell at a time. As an action, you can release the steed from its bond at any time, causing it to disappear.",
    "zh-CN": "你召来一个精魂，使其采用格外聪慧、强壮且忠诚的坐骑形态，并与你建立持久联系。坐骑出现在施法距离内一个未被占据的位置，采用你选择的形态：战马、矮种马、骆驼、麋鹿或獒犬。DM 也可能允许召来其他动物作为坐骑。坐骑使用所选形态的数据，但其类型是天界生物、精类或邪魔，由你选择，而不是原本的生物类型。此外，如果坐骑的智力为 5 或更低，其智力变为 6，并能理解你选择的一种你掌握的语言。\n\n坐骑在战斗中和战斗外都为你服务；你与它的本能联系使你们能默契作战。骑乘它时，你施放的任何仅以自身为目标的法术，也可以同时以坐骑为目标。\n\n坐骑的生命值降至 0 时便会消失，不留下实体。你也可以随时用一个动作遣散坐骑，使其消失。无论哪种情况，再次施放此法术都会召回同一个坐骑，并使其恢复至生命值上限。\n\n坐骑位于你周围 1 英里以内时，你们可以心灵交流。\n\n你不能同时与多个此法术召来的坐骑建立联系。你可以随时用一个动作解除联系，使坐骑消失。"
  },
  "spellHelp.native.flame-blade": {
    "en": "You evoke a fiery blade in your free hand. The blade is similar in size and shape to a scimitar, and it lasts for the duration. If you let go of the blade, it disappears, but you can evoke the blade again as a bonus action.\n\nYou can use your action to make a melee spell attack with the fiery blade. On a hit, the target takes 3d6 fire damage.\n\nThe flaming blade sheds bright light in a 10-foot radius and dim light for an additional 10 feet.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for every two slot levels above 2nd.",
    "zh-CN": "你在空闲的手中唤出一把火焰刀刃。它的大小和形状类似弯刀，在法术持续时间内存在。松开刀刃时，它会消失，但你可以用一个附赠动作再次唤出。\n\n你可以用一个动作，以火焰刀刃进行一次近战法术攻击。命中时，目标受到 3d6 点火焰伤害。\n\n刀刃在 10 英尺半径内发出明亮光照，并在其外侧另一个 10 英尺范围内发出微光。\n\n**升环施法。** 当你使用四环或更高环阶的法术位施放此法术时，法术位每比二环高两环，伤害便增加 1d6。"
  },
  "spellHelp.native.flaming-sphere": {
    "en": "A 5-foot diameter sphere of fire appears in an unoccupied space of your choice within range and lasts for the duration. Any creature that ends its turn within 5 feet of the sphere must make a Dexterity saving throw. The creature takes 2d6 fire damage on a failed save, or half as much damage on a successful one.\n\nAs a bonus action, you can move the sphere up to 30 feet. If you ram the sphere into a creature, that creature must make the saving throw against the sphere's damage, and the sphere stops moving this turn.\n\nWhen you move the sphere, you can direct it over barriers up to 5 feet tall and jump it across pits up to 10 feet wide. The sphere ignites flammable objects not being worn or carried, and it sheds bright light in a 20-foot radius and dim light for an additional 20 feet.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd.",
    "zh-CN": "一个直径 5 英尺的火球出现在施法距离内你选定且未被占据的位置，在法术持续时间内存在。任何在火球周围 5 英尺内结束回合的生物，都必须进行敏捷豁免；失败时受到 2d6 点火焰伤害，成功则受到一半伤害。\n\n你可以用一个附赠动作，使火球移动至多 30 英尺。如果用火球撞击一个生物，该生物必须针对火球伤害进行豁免，火球在本回合停止移动。\n\n移动火球时，你可以让它越过至多 5 英尺高的障碍，并跳过至多 10 英尺宽的坑。火球会点燃未被穿戴或携带的易燃物体，并在 20 英尺半径内发出明亮光照，在其外侧另一个 20 英尺范围内发出微光。\n\n**升环施法。** 当你使用三环或更高环阶的法术位施放此法术时，法术位每比二环高一环，伤害便增加 1d6。"
  },
  "spellHelp.native.gust-of-wind": {
    "en": "A line of strong wind 60 feet long and 10 feet wide blasts from you in a direction you choose for the spell's duration. Each creature that starts its turn in the line must succeed on a Strength saving throw or be pushed 15 feet away from you in a direction following the line.\n\nAny creature in the line must spend 2 feet of movement for every 1 foot it moves when moving closer to you.\n\nThe gust disperses gas or vapor, and it extinguishes candles, torches, and similar unprotected flames in the area. It causes protected flames, such as those of lanterns, to dance wildly and has a 50 percent chance to extinguish them.\n\nAs a bonus action on each of your turns before the spell ends, you can change the direction in which the line blasts from you.",
    "zh-CN": "法术持续时间内，一股长 60 英尺、宽 10 英尺的强风，从你身上沿选定方向吹出。在风带内开始回合的每个生物，都必须成功通过一次力量豁免，否则沿风带方向被推离你 15 英尺。\n\n风带内的生物向你靠近时，每移动 1 英尺都必须消耗 2 英尺的移动距离。\n\n强风会吹散气体和蒸汽，并熄灭区域内的蜡烛、火把等未受保护的火焰。提灯等受保护的火焰会剧烈摇曳，并有 50% 的概率熄灭。\n\n法术结束前，你可以在每个回合用一个附赠动作改变风带吹出的方向。"
  },
  "spellHelp.native.heat-metal": {
    "en": "Choose a manufactured metal object, such as a metal weapon or a suit of heavy or medium metal armor, that you can see within range. You cause the object to glow red-hot. Any creature in physical contact with the object takes 2d8 fire damage when you cast the spell. Until the spell ends, you can use a bonus action on each of your subsequent turns to cause this damage again.\n\nIf a creature is holding or wearing the object and takes the damage from it, the creature must succeed on a Constitution saving throw or drop the object if it can. If it doesn't drop the object, it has disadvantage on attack rolls and ability checks until the start of your next turn.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd.",
    "zh-CN": "选择施法距离内一个能看见的人工金属物体，例如金属武器或一套中型、重型金属护甲。你使其烧得通红。施法时，任何与该物体有实体接触的生物都会受到 2d8 点火焰伤害。法术结束前，你可以在之后的每个回合用一个附赠动作，再次造成此伤害。\n\n如果一个生物持握或穿戴该物体，并受到它造成的伤害，该生物必须成功通过一次体质豁免，否则在能够丢弃物体的情况下必须丢弃。如果没有丢弃，它的攻击检定和属性检定具有劣势，直到你的下一回合开始。\n\n**升环施法。** 当你使用三环或更高环阶的法术位施放此法术时，法术位每比二环高一环，伤害便增加 1d8。"
  },
  "spellHelp.native.levitate": {
    "en": "One creature or loose object of your choice that you can see within range rises vertically, up to 20 feet, and remains suspended there for the duration. The spell can levitate a target that weighs up to 500 pounds. An unwilling creature that succeeds on a Constitution saving throw is unaffected.\n\nThe target can move only by pushing or pulling against a fixed object or surface within reach (such as a wall or a ceiling), which allows it to move as if it were climbing. You can change the target's altitude by up to 20 feet in either direction on your turn. If you are the target, you can move up or down as part of your move. Otherwise, you can use your action to move the target, which must remain within the spell's range.\n\nWhen the spell ends, the target floats gently to the ground if it is still aloft.",
    "zh-CN": "施法距离内一个你选定且能看见的生物或未固定的物体，垂直升起至多 20 英尺，并在法术持续时间内悬浮。目标重量不能超过 500 磅。不愿接受法术的生物若成功通过体质豁免，则不受影响。\n\n目标只能通过推拉触及范围内的固定物体或表面，例如墙壁或天花板来移动，移动方式如同攀爬。在你的回合，你可以使目标向上或向下改变高度至多 20 英尺。如果你自己是目标，可以将上下移动作为自身移动的一部分；否则，需要用一个动作移动目标，且目标必须保持在施法距离内。\n\n法术结束时，如果目标仍在空中，会缓缓飘落到地面。"
  },
  "spellHelp.native.magic-mouth": {
    "en": "You implant a message within an object in range, a message that is uttered when a trigger condition is met. Choose an object that you can see and that isn't being worn or carried by another creature. Then speak the message, which must be 25 words or less, though it can be delivered over as long as 10 minutes. Finally, determine the circumstance that will trigger the spell to deliver your message.\n\nWhen that circumstance occurs, a magical mouth appears on the object and recites the message in your voice and at the same volume you spoke. If the object you chose has a mouth or something that looks like a mouth (for example, the mouth of a statue), the magical mouth appears there so that the words appear to come from the object's mouth. When you cast this spell, you can have the spell end after it delivers its message, or it can remain and repeat its message whenever the trigger occurs.\n\nThe triggering circumstance can be as general or as detailed as you like, though it must be based on visual or audible conditions that occur within 30 feet of the object. For example, you could instruct the mouth to speak when any creature moves within 30 feet of the object or when a silver bell rings within 30 feet of it.",
    "zh-CN": "你在施法距离内的一个物体中植入讯息，触发条件满足时便会说出。选择一个你能看见且未被其他生物穿戴或携带的物体。随后说出不超过 25 个词的讯息，传达它所用的时间可以长达 10 分钟。最后，确定触发法术传达讯息的条件。\n\n条件满足时，物体上出现一张魔法嘴巴，以你的声音和说话时相同的音量复述讯息。如果选定物体本身有嘴巴或类似嘴巴的部位，例如雕像的嘴，魔法嘴巴就会出现在那里，使话语仿佛出自物体的嘴。施法时，你可以选择让法术在传达一次讯息后结束，或持续存在，并在每次条件满足时重复传达。\n\n触发条件可以简单或详细，但必须基于物体周围 30 英尺内发生的视觉或声音现象。例如，你可以让嘴巴在任何生物进入物体周围 30 英尺内，或周围 30 英尺内有银铃响起时说话。"
  },
  "spellHelp.native.moonbeam": {
    "en": "A silvery beam of pale light shines down in a 5-foot radius, 40-foot high cylinder centered on a point within range. Until the spell ends, dim light fills the cylinder.\n\nWhen a creature enters the spell's area for the first time on a turn or starts its turn there, it is engulfed in ghostly flames that cause searing pain, and it must make a Constitution saving throw. It takes 2d10 radiant damage on a failed save, or half as much damage on a successful one.\n\nA shapechanger makes its saving throw with disadvantage. If it fails, it also instantly reverts to its original form and can't assume a different form until it leaves the spell's light.\n\nOn each of your turns after you cast this spell, you can use an action to move the beam up to 60 feet in any direction.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d10 for each slot level above 2nd.",
    "zh-CN": "一道银白色的苍白光束照向施法距离内的一点，形成半径 5 英尺、高 40 英尺的圆柱。法术结束前，圆柱内充满微光。\n\n一个生物在某个回合首次进入区域，或在区域内开始自己的回合时，会被幽灵般的火焰吞没，感到灼痛，并必须进行体质豁免。失败时受到 2d10 点光耀伤害，成功则受到一半伤害。\n\n变形生物在此豁免中具有劣势。豁免失败时，它还会立刻恢复原形，并在离开法术光照前无法采用其他形态。\n\n施法之后，你可以在自己的每个回合用一个动作，使光束向任意方向移动至多 60 英尺。\n\n**升环施法。** 当你使用三环或更高环阶的法术位施放此法术时，法术位每比二环高一环，伤害便增加 1d10。"
  },
  "spellHelp.native.rope-trick": {
    "en": "You touch a length of rope that is up to 60 feet long. One end of the rope then rises into the air until the whole rope hangs perpendicular to the ground. At the upper end of the rope, an invisible entrance opens to an extradimensional space that lasts until the spell ends.\n\nThe extradimensional space can be reached by climbing to the top of the rope. The space can hold as many as eight Medium or smaller creatures. The rope can be pulled into the space, making the rope disappear from view outside the space.\n\nAttacks and spells can't cross through the entrance into or out of the extradimensional space, but those inside can see out of it as if through a 3-foot-by-5-foot window centered on the rope.\n\nAnything inside the extradimensional space drops out when the spell ends.",
    "zh-CN": "你触碰一段长度不超过 60 英尺的绳子。绳子的一端升向空中，直到整条绳子垂直悬于地面上方。在绳子顶端，一个通往异次元空间的隐形入口打开，直到法术结束。\n\n爬到绳子顶端即可进入该空间。它能容纳至多 8 个中型或更小的生物。绳子可以被拉入空间，使外面的人看不见它。\n\n攻击和法术无法穿过入口进出该空间，但里面的人可以看见外面，如同透过一扇以绳子为中心、宽 3 英尺、高 5 英尺的窗。\n\n法术结束时，空间内的一切都会掉出来。"
  },
  "spellHelp.native.spike-growth": {
    "en": "The ground in a 20-foot radius centered on a point within range twists and sprouts hard spikes and thorns. The area becomes difficult terrain for the duration. When a creature moves into or within the area, it takes 2d4 piercing damage for every 5 feet it travels.\n\nThe transformation of the ground is camouflaged to look natural. Any creature that can't see the area at the time the spell is cast must make a Wisdom (Perception) check against your spell save DC to recognize the terrain as hazardous before entering it.",
    "zh-CN": "以施法距离内一点为中心，半径 20 英尺内的地面扭曲并长出坚硬的尖刺和荆棘。区域在法术持续时间内成为困难地形。一个生物进入区域或在区域内移动时，每行进 5 英尺便受到 2d4 点穿刺伤害。\n\n地面的变化被伪装成自然外观。施法时看不见该区域的生物，必须以你的法术豁免 DC 为难度进行感知（察觉）检定，才能在进入前认出这片地形的危险。"
  },
  "spellHelp.native.suggestion": {
    "en": "You suggest a course of activity (limited to a sentence or two) and magically influence a creature you can see within range that can hear and understand you. Creatures that can't be charmed are immune to this effect. The suggestion must be worded in such a manner as to make the course of action sound reasonable. Asking the creature to stab itself, throw itself onto a spear, immolate itself, or do some other obviously harmful act ends the spell.\n\nThe target must make a Wisdom saving throw. On a failed save, it pursues the course of action you described to the best of its ability. The suggested course of action can continue for the entire duration. If the suggested activity can be completed in a shorter time, the spell ends when the subject finishes what it was asked to do.\n\nYou can also specify conditions that will trigger a special activity during the duration. For example, you might suggest that a knight give her warhorse to the first beggar she meets. If the condition isn't met before the spell expires, the activity isn't performed.\n\nIf you or any of your companions damage the target, the spell ends.",
    "zh-CN": "你用一两句话建议一项行动，并以魔法影响施法距离内一个你能看见、能听见且理解你的生物。不能被魅惑的生物免疫此效果。建议的措辞必须让行动显得合理。要求生物刺伤自己、扑向长矛、焚烧自己或做其他明显有害的事，会使法术结束。\n\n目标必须进行感知豁免。失败时，它会尽力执行你描述的行动，行动可以持续整个法术持续时间。如果能在更短时间内完成，目标完成要求后，法术便会结束。\n\n你也可以指定在持续时间内触发某项行动的条件。例如，建议一个骑士把战马送给遇到的第一个乞丐。如果法术到期前条件没有满足，该行动就不会执行。\n\n你或你的任何同伴对目标造成伤害时，法术结束。"
  },
  "spellHelp.native.warding-bond": {
    "en": "This spell wards a willing creature you touch and creates a mystic connection between you and the target until the spell ends. While the target is within 60 feet of you, it gains a +1 bonus to AC and saving throws, and it has resistance to all damage. Also, each time it takes damage, you take the same amount of damage.\n\nThe spell ends if you drop to 0 hit points or if you and the target become separated by more than 60 feet. It also ends if the spell is cast again on either of the connected creatures. You can also dismiss the spell as an action.",
    "zh-CN": "此法术保护你触碰的一个自愿接受法术的生物，并在你与目标之间建立神秘联系，直到法术结束。目标位于你周围 60 英尺内时，护甲等级和豁免获得 +1 加值，并对所有伤害具有抗性。此外，每当目标受到伤害，你也会受到相同数值的伤害。\n\n你的生命值降至 0，或你与目标相距超过 60 英尺时，法术结束。任何一个相连生物再次成为此法术的目标时，原法术也会结束。你还可以用一个动作解除法术。"
  },
  "spellHelp.native.web": {
    "en": "You conjure a mass of thick, sticky webbing at a point of your choice within range. The webs fill a 20-foot cube from that point for the duration. The webs are difficult terrain and lightly obscure their area.\n\nIf the webs aren't anchored between two solid masses (such as walls or trees) or layered across a floor, wall, or ceiling, the conjured web collapses on itself, and the spell ends at the start of your next turn. Webs layered over a flat surface have a depth of 5 feet.\n\nEach creature that starts its turn in the webs or that enters them during its turn must make a\n\nDexterity saving throw. On a failed save, the creature is restrained as long as it remains in the webs or until it breaks free.\n\nA creature restrained by the webs can use its action to make a Strength check against your spell save DC. If it succeeds, it is no longer restrained.\n\nThe webs are flammable. Any 5-foot cube of webs exposed to fire burns away in 1 round, dealing 2d4 fire damage to any creature that starts its turn in the fire.",
    "zh-CN": "你在施法距离内选定的一点召出一大片浓密黏稠的蛛网，在法术持续时间内从该点延伸，充满边长 20 英尺的立方体区域。蛛网是困难地形，并使区域处于轻度遮蔽。\n\n如果蛛网没有固定在两个坚固物体之间，例如墙壁或树木，也没有铺在地板、墙壁或天花板上，它就会塌落，法术在你的下一回合开始时结束。铺在平面上的蛛网厚 5 英尺。\n\n在蛛网内开始回合，或在自己的回合进入蛛网的每个生物，都必须进行敏捷豁免。失败时，生物被束缚，直到离开蛛网或挣脱。\n\n被蛛网束缚的生物可以用一个动作，以你的法术豁免 DC 为难度进行力量检定。成功时，不再被束缚。\n\n蛛网可以燃烧。任何接触火焰的边长 5 英尺立方体蛛网，都会在 1 轮内烧尽；在火中开始回合的生物受到 2d4 点火焰伤害。"
  },
  "spellHelp.native.zone-of-truth": {
    "en": "You create a magical zone that guards against deception in a 15-foot radius sphere centered on a point of your choice within range. Until the spell ends, a creature that enters the spell's area for the first time on a turn or starts its turn there must make a Charisma saving throw. On a failed save, a creature can't speak a deliberate lie while in the radius. You know whether each creature succeeds or fails on its saving throw.\n\nAn affected creature is aware of the spell and can thus avoid answering questions to which it would normally respond with a lie. Such a creature can be evasive in its answers as long as it remains within the boundaries of the truth.",
    "zh-CN": "你以施法距离内选定的一点为中心，创造一个半径 15 英尺的球形魔法区域，防范欺骗。法术结束前，一个生物在某个回合首次进入区域，或在区域内开始自己的回合时，都必须进行魅力豁免。失败时，它在区域内不能故意说谎。你知道每个生物的豁免是成功还是失败。\n\n受影响生物知道法术的存在，因此可以避免回答那些原本会用谎言作答的问题。只要不违背事实，它也可以用含糊其辞的方式回答。"
  },
  "spellHelp.native.animate-dead": {
    "en": "This spell creates an undead servant. Choose a pile of bones or a corpse of a Medium or Small humanoid within range. Your spell imbues the target with a foul mimicry of life, raising it as an undead creature. The target becomes a skeleton if you chose bones or a zombie if you chose a corpse (the GM has the creature's game statistics).\n\nOn each of your turns, you can use a bonus action to mentally command any creature you made with this spell if the creature is within 60 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete.\n\nThe creature is under your control for 24 hours, after which it stops obeying any command you've given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature again before the current 24-hour period ends. This use of the spell reasserts your control over up to four creatures you have animated with this spell, rather than animating a new one.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, you animate or reassert control over two additional undead creatures for each slot level above 3rd. Each of the creatures must come from a different corpse or pile of bones.",
    "zh-CN": "此法术创造一名不死仆从。选择施法距离内一堆中型或小型类人生物的骨骸，或一具中型或小型类人生物尸体。你向目标注入对生命的污秽模仿，使其成为不死生物。骨骸变为骷髅，尸体变为僵尸；生物数据由 GM 提供。\n\n在自己的每个回合，可以用附赠动作，以心灵命令此法术创造、且距离你 60 英尺内的任意生物。控制多个时，可以同时命令其中任意几个或全部，对每个下达相同命令。你决定它下个回合采取的动作与移动位置，也可以下达一般命令，例如守卫某个房间或走廊。没有命令时，它只会防御敌对生物。收到命令后，会持续执行，直到任务完成。\n\n生物受你控制 24 小时，之后不再服从命令。若要再控制 24 小时，必须在当前 24 小时结束前，对它再次施放此法术。如此施放不会创造新生物，而是重新控制最多四个由此法术唤起的生物。\n\n**升环施法。** 使用 4 环及以上法术位时，法术位每比 3 环高一环，额外唤起或重新控制两个不死生物。每个必须来自不同尸体或骨骸堆。"
  },
  "spellHelp.native.beacon-of-hope": {
    "en": "This spell bestows hope and vitality. Choose any number of creatures within range. For the duration, each target has advantage on Wisdom saving throws and death saving throws, and regains the maximum number of hit points possible from any healing.",
    "zh-CN": "此法术赐予希望与活力。选择施法距离内任意数量的生物。持续时间内，每个目标的感知豁免和死亡豁免具有优势，并且从任何治疗中恢复所能恢复的最高生命值。"
  },
  "spellHelp.native.bestow-curse": {
    "en": "You touch a creature, and that creature must succeed on a Wisdom saving throw or become cursed for the duration of the spell. When you cast this spell, choose the nature of the curse from the following options:\n\n- Choose one ability score. While cursed, the target has disadvantage on ability checks and saving throws made with that ability score.\n- While cursed, the target has disadvantage on attack rolls against you.\n- While cursed, the target must make a Wisdom saving throw at the start of each of its turns. If it fails, it wastes its action that turn doing nothing.\n- While the target is cursed, your attacks and spells deal an extra 1d8 necrotic damage to the target.\n\nA *remove curse* spell ends this effect. At the GM's option, you may choose an alternative curse effect, but it should be no more powerful than those described above. The GM has final say on such a curse's effect.\n\n**At Higher Levels.** If you cast this spell using a spell slot of 4th level or higher, the duration is concentration, up to 10 minutes. If you use a spell slot of 5th level or higher, the duration is 8 hours. If you use a spell slot of 7th level or higher, the duration is 24 hours. If you use a 9th level spell slot, the spell lasts until it is dispelled. Using a spell slot of 5th level or higher grants a duration that doesn't require concentration.",
    "zh-CN": "你触碰一个生物。它必须通过感知豁免，否则在法术持续时间内被诅咒。施法时，从以下选项选择诅咒性质：\n\n- 选择一项属性。被诅咒期间，目标使用该属性进行的属性检定与豁免具有劣势。\n- 被诅咒期间，目标对你的攻击检定具有劣势。\n- 被诅咒期间，目标必须在每个自身回合开始时进行感知豁免。失败时，该回合的动作被浪费，什么也不做。\n- 目标被诅咒期间，你的攻击与法术对其额外造成 1d8 暗蚀伤害。\n\n*移除诅咒*可以结束此效果。GM 允许时，也可选择其他诅咒，但不能比上述效果更强。GM 对这种诅咒的效果有最终决定权。\n\n**升环施法。** 使用 4 环及以上法术位时，持续时间为专注，至多 10 分钟；使用 5 环及以上时，为 8 小时；使用 7 环及以上时，为 24 小时；使用 9 环时，持续到被解除。使用 5 环及以上法术位的持续时间无需专注。"
  },
  "spellHelp.native.blink": {
    "en": "Roll a d20 at the end of each of your turns for the duration of the spell. On a roll of 11 or higher, you vanish from your current plane of existence and appear in the Ethereal Plane (the spell fails and the casting is wasted if you were already on that plane). At the start of your next turn, and when the spell ends if you are on the Ethereal Plane, you return to an unoccupied space of your choice that you can see within 10 feet of the space you vanished from. If no unoccupied space is available within that range, you appear in the nearest unoccupied space (chosen at random if more than one space is equally near). You can dismiss this spell as an action.\n\nWhile on the Ethereal Plane, you can see and hear the plane you originated from, which is cast in shades of gray, and you can't see anything there more than 60 feet away. You can only affect and be affected by other creatures on the Ethereal Plane. Creatures that aren't there can't perceive you or interact with you, unless they have the ability to do so.",
    "zh-CN": "持续时间内，每个自身回合结束时掷 d20。结果为 11 或更高，你从当前位面消失，出现在以太位面；若已经在那里，法术失败，施法被浪费。下个回合开始时，以及法术结束而你仍在以太位面时，返回消失位置 10 英尺内、你能看见且未被占据的自选位置。范围内没有空位时，出现在最近空位；若多个位置同样近，则随机选择。可以用动作解除此法术。\n\n在以太位面时，你能看见、听见原位面，那里呈灰色，但看不见超过 60 英尺的事物。只能影响同在以太位面的生物，也只能受它们影响。不在该位面的生物无法感知你或与你互动，除非具有这样的能力。"
  },
  "spellHelp.native.call-lightning": {
    "en": "A storm cloud appears in the shape of a cylinder that is 10 feet tall with a 60-foot radius, centered on a point you can see within range directly above you. The spell fails if you can't see a point in the air where the storm cloud could appear (for example, if you are in a room that can't accommodate the cloud).\n\nWhen you cast the spell, choose a point you can see under the cloud. A bolt of lightning flashes down from the cloud to that point. Each creature within 5 feet of that point must make a Dexterity saving throw. A creature takes 3d10 lightning damage on a failed save, or half as much damage on a successful one. On each of your turns until the spell ends, you can use your action to call down lightning in this way again, targeting the same point or a different one.\n\nIf you are outdoors in stormy conditions when you cast this spell, the spell gives you control over the existing storm instead of creating a new one. Under such conditions, the spell's damage increases by 1d10.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 4th or higher level, the damage increases by 1d10 for each slot level above 3rd.",
    "zh-CN": "你正上方、施法距离内可见的一点出现圆柱形雷云，高 10 英尺、半径 60 英尺。若看不见可容纳雷云的空中位置，例如房间容不下雷云，法术失败。\n\n施法时，在雷云下选择一个可见点，闪电从云中劈下。该点 5 英尺内每个生物都进行敏捷豁免，失败时受到 3d10 闪电伤害，成功时一半。法术结束前，每个自身回合都可以用动作再次这样召雷，指定同一点或其他点。\n\n若在户外雷暴天气施法，法术使你控制现有风暴，而非创造新的雷云。此时伤害增加 1d10。\n\n**升环施法。** 使用 4 环及以上法术位时，法术位每比 3 环高一环，伤害增加 1d10。"
  },
  "spellHelp.native.clairvoyance": {
    "en": "You create an invisible sensor within range in a location familiar to you (a place you have visited or seen before) or in an obvious location that is unfamiliar to you (such as behind a door, around a corner, or in a grove of trees). The sensor remains in place for the duration, and it can't be attacked or otherwise interacted with.\n\nWhen you cast the spell, you choose seeing or hearing. You can use the chosen sense through the sensor as if you were in its space. As your action, you can switch between seeing and hearing.\n\nA creature that can see the sensor (such as a creature benefiting from *see invisibility* or truesight) sees a luminous, intangible orb about the size of your fist.",
    "zh-CN": "在施法距离内，你熟悉的位置，例如曾到访或见过的地方，或不熟悉但明显的位置，例如门后、转角或树林中，创造一个隐形感知器。它在持续时间内固定于原处，无法被攻击或以其他方式互动。\n\n施法时选择视觉或听觉，可以通过感知器使用所选感官，仿佛身处其位置。可以用动作在视觉与听觉之间切换。\n\n能看见感知器的生物，例如受益于*识破隐形*或真实视觉的生物，会看见一颗约拳头大小、发光且无实体的球。"
  },
  "spellHelp.native.conjure-animals": {
    "en": "You summon fey spirits that take the form of beasts and appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears:\n\n- One beast of challenge rating 2 or lower\n- Two beasts of challenge rating 1 or lower\n- Four beasts of challenge rating 1/2 or lower\n- Eight beasts of challenge rating 1/4 or lower\n\nEach beast is also considered fey, and it disappears when it drops to 0 hit points or when the spell ends.\n\nThe summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which has its own turns. They obey any verbal commands that you issue to them (no action required by you). If you don't issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.\n\nThe GM has the creatures' statistics.\n\n**At Higher Levels.** When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 5th-level slot, three times as many with a 7th-level slot, and four times as many with a 9th-level slot.",
    "zh-CN": "你召唤精类灵体，使其采用野兽形态，出现在施法距离内可见的未占据位置。从以下出现方式中选择一种：\n\n- 一只挑战等级不超过 2 的野兽\n- 两只挑战等级不超过 1 的野兽\n- 四只挑战等级不超过 1/2 的野兽\n- 八只挑战等级不超过 1/4 的野兽\n\n每只野兽也视为精类，生命值降至 0 或法术结束时消失。\n\n召唤的生物友善对待你和同伴。将它们作为一组掷先攻，有自己的回合。它们服从你下达的口头命令，无需你花费动作。没有命令时，会防御敌对生物，但不会采取其他动作。\n\nGM 提供生物数据。\n\n**升环施法。** 使用某些更高环阶法术位时，仍选择上述一种方式，但出现数量增加：5 环法术位为两倍，7 环为三倍，9 环为四倍。"
  },
  "spellHelp.native.counterspell": {
    "en": "You attempt to interrupt a creature in the process of casting a spell. If the creature is casting a spell of 3rd level or lower, its spell fails and has no effect. If it is casting a spell of 4th level or higher, make an ability check using your spellcasting ability. The DC equals 10 + the spell's level. On a success, the creature's spell fails and has no effect.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the interrupted spell has no effect if its level is less than or equal to the level of the spell slot you used.",
    "zh-CN": "你尝试打断生物正在施放的法术。若该法术为 3 环或更低，自动失败，没有效果。若为 4 环或更高，使用你的施法属性进行属性检定，DC 为 10 + 该法术环阶。成功时，生物的法术失败，没有效果。\n\n**升环施法。** 使用 4 环及以上法术位时，若被打断法术的环阶不超过你使用的法术位环阶，它就没有效果。"
  },
  "spellHelp.native.create-food-and-water": {
    "en": "You create 45 pounds of food and 30 gallons of water on the ground or in containers within range, enough to sustain up to fifteen humanoids or five steeds for 24 hours. The food is bland but nourishing, and spoils if uneaten after 24 hours. The water is clean and doesn't go bad.",
    "zh-CN": "你在施法距离内的地面或容器中创造 45 磅食物与 30 加仑水，足以供养最多十五名类人生物或五匹坐骑 24 小时。食物味淡但营养充足，24 小时后未吃掉的部分会腐坏。水是干净的，不会变质。"
  },
  "spellHelp.native.daylight": {
    "en": "A 60-foot radius sphere of light spreads out from a point you choose within range. The sphere is bright light and sheds dim light for an additional 60 feet.\n\nIf you chose a point on an object you are holding or one that isn't being worn or carried, the light shines from the object and moves with it. Completely covering the affected object with an opaque object, such as a bowl or a helm, blocks the light.\n\nIf any of this spell's area overlaps with an area of darkness created by a spell of 3rd level or lower, the spell that created the darkness is dispelled.",
    "zh-CN": "从施法距离内自选的一点，扩散出半径 60 英尺的光球。球内为明亮光照，之外再延伸 60 英尺微光。\n\n若所选点位于你持握的物体，或未被穿戴、携带的物体上，光从该物体发出并随其移动。用碗、头盔等不透明物体完全覆盖目标，可以阻挡光。\n\n若此法术的区域与 3 环及以下法术创造的黑暗区域重叠，创造黑暗的法术被解除。"
  },
  "spellHelp.native.dispel-magic": {
    "en": "Choose one creature, object, or magical effect within range. Any spell of 3rd level or lower on the target ends. For each spell of 4th level or higher on the target, make an ability check using your spellcasting ability. The DC equals 10 + the spell's level. On a successful check, the spell ends.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, you automatically end the effects of a spell on the target if the spell's level is equal to or less than the level of the spell slot you used.",
    "zh-CN": "选择施法距离内一个生物、物体或魔法效果。目标身上所有 3 环及以下法术结束。每个 4 环及以上法术，都需要用你的施法属性进行属性检定，DC 为 10 + 该法术环阶；检定成功时，该法术结束。\n\n**升环施法。** 使用 4 环及以上法术位时，若目标身上法术的环阶不超过你使用的法术位环阶，就自动结束其效果。"
  },
  "spellHelp.native.fear": {
    "en": "You project a phantasmal image of a creature's worst fears. Each creature in a 30-foot cone must succeed on a Wisdom saving throw or drop whatever it is holding and become frightened for the duration.\n\nWhile frightened by this spell, a creature must take the Dash action and move away from you by the safest available route on each of its turns, unless there is nowhere to move. If the creature ends its turn in a location where it doesn't have line of sight to you, the creature can make a Wisdom saving throw. On a successful save, the spell ends for that creature.",
    "zh-CN": "你投射出生物最深恐惧的幻影。30 英尺锥形区域内每个生物必须通过感知豁免，否则丢下所有持握物品，并在持续时间内陷入恐慌。\n\n受此法术恐慌的生物，必须在每个自身回合采取疾跑动作，沿最安全的可行路线远离你，除非无处可去。若在回合结束时所在位置无法看见你，可以进行感知豁免；成功时，此法术对该生物结束。"
  },
  "spellHelp.native.fireball": {
    "en": "A bright streak flashes from your pointing finger to a point you choose within range and then blossoms with a low roar into an explosion of flame. Each creature in a 20-foot radius sphere centered on that point must make a Dexterity saving throw. A target takes 8d6 fire damage on a failed save, or half as much damage on a successful one.\n\nThe fire spreads around corners. It ignites flammable objects in the area that aren't being worn or carried.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd.",
    "zh-CN": "一道明亮光迹从你伸出的手指射向施法距离内自选的一点，伴随低吼炸成火焰。以该点为中心、半径 20 英尺球形区域内每个生物都进行敏捷豁免。失败时受到 8d6 火焰伤害，成功时一半。\n\n火焰会绕过转角，点燃区域内未被穿戴或携带的易燃物体。\n\n**升环施法。** 使用 4 环及以上法术位时，法术位每比 3 环高一环，伤害增加 1d6。"
  },
  "spellHelp.native.fly": {
    "en": "You touch a willing creature. The target gains a flying speed of 60 feet for the duration. When the spell ends, the target falls if it is still aloft, unless it can stop the fall.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd.",
    "zh-CN": "你触碰一个自愿生物。持续时间内，它获得 60 英尺飞行速度。法术结束时，若仍在空中就会坠落，除非能够阻止坠落。\n\n**升环施法。** 使用 4 环及以上法术位时，法术位每比 3 环高一环，可以额外指定一个生物为目标。"
  },
  "spellHelp.native.gaseous-form": {
    "en": "You transform a willing creature you touch, along with everything it's wearing and carrying, into a misty cloud for the duration. The spell ends if the creature drops to 0 hit points. An incorporeal creature isn't affected.\n\nWhile in this form, the target's only method of movement is a flying speed of 10 feet. The target can enter and occupy the space of another creature. The target has resistance to nonmagical damage, and it has advantage on Strength, Dexterity, and Constitution saving throws. The target can pass through small holes, narrow openings, and even mere cracks, though it treats liquids as though they were solid surfaces. The target can't fall and remains hovering in the air even when stunned or otherwise incapacitated.\n\nWhile in the form of a misty cloud, the target can't talk or manipulate objects, and any objects it was carrying or holding can't be dropped, used, or otherwise interacted with. The target can't attack or cast spells.",
    "zh-CN": "你触碰一个自愿生物，将它及所有穿戴、携带物品变为雾团，持续至法术结束。生物生命值降至 0 时，法术结束。无实体生物不受影响。\n\n此形态下，目标只能以 10 英尺飞行速度移动，可以进入并占据其他生物的位置。对非魔法伤害具有抗性，力量、敏捷与体质豁免具有优势。能穿过小孔、狭窄开口，甚至缝隙，但将液体视为固体表面。不会坠落，即使震慑或其他失能状态下，仍悬浮在空中。\n\n雾团形态不能说话或操作物体；此前持握、携带的物体不能丢下、使用或以其他方式互动。目标不能攻击或施法。"
  },
  "spellHelp.native.glyph-of-warding": {
    "en": "When you cast this spell, you inscribe a glyph that harms other creatures, either upon a surface (such as a table or a section of floor or wall) or within an object that can be closed (such as a book, a scroll, or a treasure chest) to conceal the glyph. The glyph can cover an area no larger than 10 feet in diameter. If the surface or object is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered.\n\nThe glyph is nearly invisible and requires a successful Intelligence (Investigation) check against your spell save DC to be found.\n\nYou decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, the most typical triggers include touching or standing on the glyph, removing another object covering the glyph, approaching within a certain distance of the glyph, or manipulating the object on which the glyph is inscribed. For glyphs inscribed within an object, the most common triggers include opening that object, approaching within a certain distance of the object, or seeing or reading the glyph. Once a glyph is triggered, this spell ends.\n\nYou can further refine the trigger so the spell activates only under certain circumstances or according to physical characteristics (such as height or weight), creature kind (for example, the ward could be set to affect aberrations or drow), or alignment. You can also set conditions for creatures that don't trigger the glyph, such as those who say a certain password.\n\nWhen you inscribe the glyph, choose *explosive runes* or a *spell glyph*.\n\n**Explosive Runes**. When triggered, the glyph erupts with magical energy in a 20-foot radius sphere centered on the glyph. The sphere spreads around corners. Each creature in the area must make a Dexterity saving throw. A creature takes 5d8 acid, cold, fire, lightning, or thunder damage on a failed saving throw (your choice when you create the glyph), or half as much damage on a successful one.\n\n**Spell Glyph**. You can store a prepared spell of 3rd level or lower in the glyph by casting it as part of creating the glyph. The spell must target a single creature or an area. The spell being stored has no immediate effect when cast in this way. When the glyph is triggered, the stored spell is cast. If the spell has a target, it targets the creature that triggered the glyph. If the spell affects an area, the area is centered on that creature. If the spell summons hostile creatures or creates harmful objects or traps, they appear as close as possible to the intruder and attack it. If the spell requires concentration, it lasts until the end of its full duration.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the damage of an *explosive runes* glyph increases by 1d8 for each slot level above 3rd. If you create a *spell glyph*, you can store any spell of up to the same level as the slot you use for the *glyph of warding*.",
    "zh-CN": "施放时，在表面上，例如桌面、地板或墙壁，或可关闭的物体内部，例如书、卷轴或宝箱，刻写一道伤害其他生物的符文，并借此隐藏符文。覆盖区域的直径不能超过 10 英尺。表面或物体被移到距离施法位置超过 10 英尺处时，符文破坏，法术结束且不触发。\n\n符文几乎看不见。必须通过智力（调查）检定，DC 等于你的法术豁免 DC，才能发现。\n\n施法时决定触发方式。表面符文通常因触碰、站上符文、移除覆盖物、靠近一定距离，或操作刻有符文的物体而触发。物体内部符文通常因打开物体、靠近一定距离，或看见、阅读符文而触发。符文触发后，此法术结束。\n\n可以进一步细化条件，使其仅在特定情境下，或根据身高、体重等身体特征、生物类型，例如异怪或卓尔，或阵营而触发。也可以设定不触发的条件，例如说出特定口令。\n\n刻写时，选择*爆炸符文*或*法术符文*。\n\n***爆炸符文。*** 触发时，符文在以自身为中心、半径 20 英尺的球形区域释放魔法能量，绕过转角。区域内每个生物都进行敏捷豁免，失败时受到 5d8 强酸、冷冻、火焰、闪电或雷鸣伤害，类型在创造时自选；成功时一半。\n\n***法术符文。*** 可以在创造符文时施放一个已准备的 3 环及以下法术，将其储存其中。法术必须指定一个生物或区域为目标；这样施放没有即时效果。符文触发时，储存的法术施放出来：单目标法术指定触发者，区域法术以触发者为中心。若召唤敌对生物，或创造有害物体、陷阱，它们会尽可能靠近闯入者出现并攻击它。需要专注的法术会持续到完整持续时间结束。\n\n**升环施法。** 使用 4 环及以上法术位时，法术位每比 3 环高一环，爆炸符文伤害增加 1d8。创造法术符文时，所储存法术的环阶可以最高等于施放*守护刻文*所用法术位的环阶。"
  },
  "spellHelp.native.haste": {
    "en": "Choose a willing creature that you can see within range. Until the spell ends, the target's speed is doubled, it gains a +2 bonus to AC, it has advantage on Dexterity saving throws, and it gains an additional action on each of its turns. That action can be used only to take the Attack (one weapon attack only), Dash, Disengage, Hide, or Use an Object action.\n\nWhen the spell ends, the target can't move or take actions until after its next turn, as a wave of lethargy sweeps over it.",
    "zh-CN": "选择施法距离内一个可见的自愿生物。法术结束前，其速度加倍，AC 获得 +2 加值，敏捷豁免具有优势，每个自身回合还获得一个额外动作。此动作只能用于攻击（仅一次武器攻击）、疾跑、撤离、躲藏或使用物品。\n\n法术结束时，一阵倦怠袭来，目标在其下个回合结束前不能移动或采取动作。"
  },
  "spellHelp.native.hypnotic-pattern": {
    "en": "You create a twisting pattern of colors that weaves through the air inside a 30-foot cube within range. The pattern appears for a moment and vanishes. Each creature in the area who sees the pattern must make a Wisdom saving throw. On a failed save, the creature becomes charmed for the duration. While charmed by this spell, the creature is incapacitated and has a speed of 0.\n\nThe spell ends for an affected creature if it takes any damage or if someone else uses an action to shake the creature out of its stupor.",
    "zh-CN": "在施法距离内边长 30 英尺的立方体区域中，创造在空中交织的扭曲彩色图案。图案短暂出现后消失。区域内每个看见图案的生物都进行感知豁免，失败时在持续时间内被魅惑。受此法术魅惑期间，生物失能，速度为 0。\n\n受影响生物受到任何伤害，或其他人用动作将其摇醒时，此法术对该生物结束。"
  },
  "spellHelp.native.lightning-bolt": {
    "en": "A stroke of lightning forming a line 100 feet long and 5 feet wide blasts out from you in a direction you choose. Each creature in the line must make a Dexterity saving throw. A creature takes 8d6 lightning damage on a failed save, or half as much damage on a successful one.\n\nThe lightning ignites flammable objects in the area that aren't being worn or carried.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd.",
    "zh-CN": "一道长 100 英尺、宽 5 英尺的直线闪电，沿你选择的方向从你身上轰出。直线内每个生物都进行敏捷豁免，失败时受到 8d6 闪电伤害，成功时一半。\n\n闪电会点燃区域内未被穿戴或携带的易燃物体。\n\n**升环施法。** 使用 4 环及以上法术位时，法术位每比 3 环高一环，伤害增加 1d6。"
  },
  "spellHelp.native.magic-circle": {
    "en": "You create a 10-foot radius, 20-foot tall cylinder of magical energy centered on a point on the ground that you can see within range. Glowing runes appear wherever the cylinder intersects with the floor or other surface.\n\nChoose one or more of the following types of creatures: celestials, elementals, fey, fiends, or undead. The circle affects a creature of the chosen type in the following ways:\n\n- The creature can't willingly enter the cylinder by nonmagical means. If the creature tries to use teleportation or interplanar travel to do so, it must first succeed on a Charisma saving throw.\n- The creature has disadvantage on attack rolls against targets within the cylinder.\n- Targets within the cylinder can't be charmed, frightened, or possessed by the creature.\n\nWhen you cast this spell, you can elect to cause its magic to operate in the reverse direction, preventing a creature of the specified type from leaving the cylinder and protecting targets outside it.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the duration increases by 1 hour for each slot level above 3rd.",
    "zh-CN": "在施法距离内地面上可见的一点，创造半径 10 英尺、高 20 英尺的魔法能量圆柱。圆柱与地面或其他表面相交处出现发光符文。\n\n从天界、元素、精类、邪魔或不死生物中选择一种或多种。圆阵对所选类型生物产生以下效果：\n\n- 不能主动以非魔法方式进入圆柱。若尝试用传送或位面旅行进入，必须先通过魅力豁免。\n- 对圆柱内目标的攻击检定具有劣势。\n- 圆柱内目标不能被该生物魅惑、恐慌或附身。\n\n施法时，也可以选择反转效果，阻止所选类型生物离开圆柱，并保护圆柱外的目标。\n\n**升环施法。** 使用 4 环及以上法术位时，法术位每比 3 环高一环，持续时间增加 1 小时。"
  },
  "spellHelp.native.major-image": {
    "en": "You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 20-foot cube. The image appears at a spot that you can see within range and lasts for the duration. It seems completely real, including sounds, smells, and temperature appropriate to the thing depicted. You can't create sufficient heat or cold to cause damage, a sound loud enough to deal thunder damage or deafen a creature, or a smell that might sicken a creature (like a troglodyte's stench).\n\nAs long as you are within range of the illusion, you can use your action to cause the image to move to any other spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking. Similarly, you can cause the illusion to make different sounds at different times, even making it carry on a conversation, for example.\n\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and its other sensory qualities become faint to the creature.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 6th level or higher, the spell lasts until dispelled, without requiring your concentration.",
    "zh-CN": "创造一个物体、生物或其他可见现象的影像，大小不超过边长 20 英尺的立方体。它出现在施法距离内可见的位置，并在持续时间内存在。影像仿佛完全真实，包含对应的声音、气味与温度。但不能创造足以造成伤害的冷热、足以造成雷鸣伤害或耳聋的响声，或能使生物患病的气味，例如战蜥人的恶臭。\n\n只要你位于幻象的施法距离内，就可以用动作将其移到施法距离内其他位置，并改变外观，让动作显得自然。例如移动生物影像时，可以使其仿佛在走路。同样，可以使幻象在不同时刻发出不同声音，例如进行对话。\n\n与影像进行实体互动，就会发现它是幻象，因为物体可穿过它。生物可以用动作检查影像，通过智力（调查）检定，DC 等于你的法术豁免 DC，即可识破。识破者可以看穿影像，其他感官效果对它也会变得微弱。\n\n**升环施法。** 使用 6 环及以上法术位时，法术持续到被解除，无需专注。"
  },
  "spellHelp.native.mass-healing-word": {
    "en": "As you call out words of restoration, up to six creatures of your choice that you can see within range regain hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on undead or constructs.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the healing increases by 1d4 for each slot level above 3rd.",
    "zh-CN": "你呼喊恢复之语，使施法距离内最多六个自选、可见生物，恢复等于 1d4 + 你的施法属性调整值的生命值。对不死生物与构装体无效。\n\n**升环施法。** 使用 4 环及以上法术位时，法术位每比 3 环高一环，治疗量增加 1d4。"
  },
  "spellHelp.native.meld-into-stone": {
    "en": "You step into a stone object or surface large enough to fully contain your body, melding yourself and all the equipment you carry with the stone for the duration. Using your movement, you step into the stone at a point you can touch. Nothing of your presence remains visible or otherwise detectable by nonmagical senses.\n\nWhile merged with the stone, you can't see what occurs outside it, and any Wisdom (Perception) checks you make to hear sounds outside it are made with disadvantage. You remain aware of the passage of time and can cast spells on yourself while merged in the stone. You can use your movement to leave the stone where you entered it, which ends the spell. You otherwise can't move.\n\nMinor physical damage to the stone doesn't harm you, but its partial destruction or a change in its shape (to the extent that you no longer fit within it) expels you and deals 6d6 bludgeoning damage to you. The stone's complete destruction (or transmutation into a different substance) expels you and deals 50 bludgeoning damage to you. If expelled, you fall prone in an unoccupied space closest to where you first entered.",
    "zh-CN": "你踏入足以容纳全身的石质物体或表面，将自身和所有携带装备融入石中，持续至法术结束。用移动从可触碰的一点进入；非魔法感官无法看见或以其他方式探知你的存在。\n\n融入时看不见外界，聆听外界声音的感知（察觉）检定具有劣势。仍知晓时间流逝，并能对自身施法。可以用移动从进入处离开，结束法术；除此之外不能移动。\n\n石头受到轻微实体损伤不会伤害你；部分被毁或形状变化，使其不能再容纳你时，会将你逐出并造成 6d6 钝击伤害。完全毁坏，或转化为其他物质时，会将你逐出并造成 50 钝击伤害。被逐出时，在离最初进入点最近的未占据位置倒地。"
  },
  "spellHelp.native.nondetection": {
    "en": "For the duration, you hide a target that you touch from divination magic. The target can be a willing creature or a place or an object no larger than 10 feet in any dimension. The target can't be targeted by any divination magic or perceived through magical scrying sensors.",
    "zh-CN": "持续时间内，使你触碰的目标躲避预言魔法。目标可以是一个自愿生物，或任何方向尺寸都不超过 10 英尺的地点或物体。任何预言魔法都不能将其指定为目标，也无法通过魔法探知感知器察觉它。"
  },
  "spellHelp.native.phantom-steed": {
    "en": "A Large quasi-real, horselike creature appears on the ground in an unoccupied space of your choice within range. You decide the creature's appearance, but it is equipped with a saddle, bit, and bridle. Any of the equipment created by the spell vanishes in a puff of smoke if it is carried more than 10 feet away from the steed.\n\nFor the duration, you or a creature you choose can ride the steed. The creature uses the statistics for a riding horse, except it has a speed of 100 feet and can travel 10 miles in an hour, or 13 miles at a fast pace. When the spell ends, the steed gradually fades, giving the rider 1 minute to dismount. The spell ends if you use an action to dismiss it or if the steed takes any damage.",
    "zh-CN": "施法距离内自选的未占据地面位置，出现一只大型、半真实的马形生物。你决定外观，但它配有鞍、衔铁与缰绳。法术创造的装备被带离坐骑超过 10 英尺时，化为一团烟消失。\n\n持续时间内，你或自选生物可以骑乘。它使用骑乘马的数据，但速度为 100 英尺，每小时可行进 10 英里，快速步调为 13 英里。法术结束时，坐骑逐渐淡去，给予骑手 1 分钟下马。你用动作解除法术，或坐骑受到任何伤害时，法术结束。"
  },
  "spellHelp.native.plant-growth": {
    "en": "This spell channels vitality into plants within a specific area. There are two possible uses for the spell, granting either immediate or long-term benefits.\n\nIf you cast this spell using 1 action, choose a point within range. All normal plants in a 100-foot radius centered on that point become thick and overgrown. A creature moving through the area must spend 4 feet of movement for every 1 foot it moves.\n\nYou can exclude one or more areas of any size within the spell's area from being affected.\n\nIf you cast this spell over 8 hours, you enrich the land. All plants in a half-mile radius centered on a point within range become enriched for 1 year. The plants yield twice the normal amount of food when harvested.",
    "zh-CN": "此法术向特定区域的植物注入活力，有两种用途，分别给予即时或长期益处。\n\n若用 1 个动作施放，在施法距离内选择一点。以此点为中心、半径 100 英尺内的普通植物变得茂密、过度生长。生物在此区域每移动 1 英尺，必须消耗 4 英尺移动力。\n\n可以在法术区域内排除一个或多个任意大小的区域，使其不受影响。\n\n若花费 8 小时施放，则使土地肥沃。以施法距离内一点为中心、半径半英里内的植物，获得持续 1 年的滋养；收获时食物产量为通常的两倍。"
  },
  "spellHelp.native.protection-from-energy": {
    "en": "For the duration, the willing creature you touch has resistance to one damage type of your choice: acid, cold, fire, lightning, or thunder.",
    "zh-CN": "持续时间内，你触碰的自愿生物获得对一种自选伤害类型的抗性：强酸、冷冻、火焰、闪电或雷鸣。"
  },
  "spellHelp.native.remove-curse": {
    "en": "At your touch, all curses affecting one creature or object end. If the object is a cursed magic item, its curse remains, but the spell breaks its owner's attunement to the object so it can be removed or discarded.",
    "zh-CN": "触碰时，影响一个生物或物体的所有诅咒结束。若物体是受诅咒魔法物品，诅咒仍保留，但此法术会打破持有者与它的同调，使其能够被取下或丢弃。"
  },
  "spellHelp.native.revivify": {
    "en": "You touch a creature that has died within the last minute. That creature returns to life with 1 hit point. This spell can't return to life a creature that has died of old age, nor can it restore any missing body parts.",
    "zh-CN": "你触碰一个在过去 1 分钟内死亡的生物，使其复活并具有 1 点生命值。不能复活因衰老死亡的生物，也不能恢复缺失的身体部位。"
  },
  "spellHelp.native.sending": {
    "en": "You send a short message of twenty-five words or less to a creature with which you are familiar. The creature hears the message in its mind, recognizes you as the sender if it knows you, and can answer in a like manner immediately. The spell enables creatures with Intelligence scores of at least 1 to understand the meaning of your message.\n\nYou can send the message across any distance and even to other planes of existence, but if the target is on a different plane than you, there is a 5 percent chance that the message doesn't arrive.",
    "zh-CN": "向一个你熟悉的生物发送最多二十五个词的短讯。它在脑海中听见讯息；若认识你，会识别出你是发送者，并能立即以相同方式回应。此法术使智力至少为 1 的生物能理解讯息含义。\n\n可以跨越任意距离，甚至发送到其他位面；但目标与你处于不同位面时，有 5% 概率无法送达。"
  },
  "spellHelp.native.sleet-storm": {
    "en": "Until the spell ends, freezing rain and sleet fall in a 20-foot tall cylinder with a 40-foot radius centered on a point you choose within range. The area is heavily obscured, and exposed flames in the area are doused.\n\nThe ground in the area is covered with slick ice, making it difficult terrain. When a creature enters the spell's area for the first time on a turn or starts its turn there, it must make a Dexterity saving throw. On a failed save, it falls prone.\n\nIf a creature starts its turn in the spell's area and is concentrating on a spell, the creature must make a successful Constitution saving throw against your spell save DC or lose concentration.",
    "zh-CN": "法术结束前，以施法距离内自选的一点为中心、半径 40 英尺、高 20 英尺的圆柱区域中，降下冻雨与雨夹雪。区域为重度遮蔽，暴露的火焰熄灭。\n\n地面覆盖湿滑冰层，成为困难地形。生物在一个回合中首次进入区域，或在那里开始自身回合时，必须进行敏捷豁免；失败则倒地。\n\n在区域内开始自身回合、且正在专注于法术的生物，必须通过体质豁免，DC 等于你的法术豁免 DC，否则失去专注。"
  },
  "spellHelp.native.slow": {
    "en": "You alter time around up to six creatures of your choice in a 40-foot cube within range. Each target must succeed on a Wisdom saving throw or be affected by this spell for the duration.\n\nAn affected target's speed is halved, it takes a -2 penalty to AC and Dexterity saving throws, and it can't use reactions. On its turn, it can use either an action or a bonus action, not both. Regardless of the creature's abilities or magic items, it can't make more than one melee or ranged attack during its turn.\n\nIf the creature attempts to cast a spell with a casting time of 1 action, roll a d20. On an 11 or higher, the spell doesn't take effect until the creature's next turn, and the creature must use its action on that turn to complete the spell. If it can't, the spell is wasted.\n\nA creature affected by this spell makes another Wisdom saving throw at the end of each of its turns. On a successful save, the effect ends for it.",
    "zh-CN": "扭转施法距离内边长 40 英尺立方体中，最多六个自选生物周围的时间。每个目标必须通过感知豁免，否则在持续时间内受到影响。\n\n受影响目标的速度减半，AC 与敏捷豁免承受 -2 减值，不能使用反应。自身回合中只能用动作或附赠动作之一，不能兼用。无论能力或魔法物品如何，该回合最多只能进行一次近战或远程攻击。\n\n若尝试施放施法时间为 1 个动作的法术，掷 d20。结果为 11 或更高时，法术直到该生物下个回合才生效，并且必须在该回合用动作完成施法；若不能完成，法术被浪费。\n\n每个自身回合结束时，受影响生物再进行感知豁免；成功则对其结束效果。"
  },
  "spellHelp.native.speak-with-dead": {
    "en": "You grant the semblance of life and intelligence to a corpse of your choice within range, allowing it to answer the questions you pose. The corpse must still have a mouth and can't be undead. The spell fails if the corpse was the target of this spell within the last 10 days.\n\nUntil the spell ends, you can ask the corpse up to five questions. The corpse knows only what it knew in life, including the languages it knew. Answers are usually brief, cryptic, or repetitive, and the corpse is under no compulsion to offer a truthful answer if you are hostile to it or it recognizes you as an enemy. This spell doesn't return the creature's soul to its body, only its animating spirit. Thus, the corpse can't learn new information, doesn't comprehend anything that has happened since it died, and can't speculate about future events.",
    "zh-CN": "赋予施法距离内自选尸体类似生命与智能的状态，让它回答你的问题。尸体必须仍有嘴，且不能是不死生物。过去 10 天内曾成为此法术目标的尸体，会使法术失败。\n\n法术结束前，可以询问最多五个问题。尸体只知道生前知识，包括掌握的语言。答案通常简短、含糊或重复。若你敌视它，或它认出你是敌人，它没有如实回答的义务。法术仅唤回使其活动的灵性，不会让灵魂返回身体。因此，它不能学习新信息，不理解死后发生的事，也不能推测未来。"
  },
  "spellHelp.native.speak-with-plants": {
    "en": "You imbue plants within 30 feet of you with limited sentience and animation, giving them the ability to communicate with you and follow your simple commands. You can question plants about events in the spell's area within the past day, gaining information about creatures that have passed, weather, and other circumstances.\n\nYou can also turn difficult terrain caused by plant growth (such as thickets and undergrowth) into ordinary terrain that lasts for the duration. Or you can turn ordinary terrain where plants are present into difficult terrain that lasts for the duration, causing vines and branches to hinder pursuers, for example.\n\nPlants might be able to perform other tasks on your behalf, at the GM's discretion. The spell doesn't enable plants to uproot themselves and move about, but they can freely move branches, tendrils, and stalks.\n\nIf a plant creature is in the area, you can communicate with it as if you shared a common language, but you gain no magical ability to influence it.\n\nThis spell can cause the plants created by the *entangle* spell to release a restrained creature.",
    "zh-CN": "赋予你 30 英尺内的植物有限意识与活动能力，使其与你交流、服从简单命令。可以询问过去一天法术区域内的事件，了解经过的生物、天气等情况。\n\n可以使植物生长造成的困难地形，例如灌丛或茂密植被，变为普通地形，持续至法术结束。也可以使有植物的普通地形变为困难地形，例如用藤蔓和枝条阻碍追兵，持续至法术结束。\n\nGM 可以决定植物还能代你执行其他任务。法术不会让它们拔根移动，但能自由活动枝条、卷须和茎秆。\n\n区域内有植物生物时，可以像共享同一语言一样交流，但不会获得以魔法影响它的能力。\n\n此法术可以使*纠缠术*创造的植物释放被束缚的生物。"
  },
  "spellHelp.native.spirit-guardians": {
    "en": "You call forth spirits to protect you. They flit around you to a distance of 15 feet for the duration. If you are good or neutral, their spectral form appears angelic or fey (your choice). If you are evil, they appear fiendish.\n\nWhen you cast this spell, you can designate any number of creatures you can see to be unaffected by it. An affected creature's speed is halved in the area, and when the creature enters the area for the first time on a turn or starts its turn there, it must make a Wisdom saving throw. On a failed save, the creature takes 3d8 radiant damage (if you are good or neutral) or 3d8 necrotic damage (if you are evil). On a successful save, the creature takes half as much damage.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d8 for each slot level above 3rd.",
    "zh-CN": "召来灵体保护你，在持续时间内于你周围 15 英尺范围飞掠。善良或中立阵营者的灵体呈天使或精类形态，自选其一；邪恶者的灵体呈邪魔形态。\n\n施法时，可以指定任意数量可见生物不受影响。受影响生物在区域内速度减半；在一个回合中首次进入，或在那里开始自身回合时，必须进行感知豁免。失败时受到 3d8 光耀伤害（你为善良或中立）或 3d8 暗蚀伤害（你为邪恶）；成功时伤害一半。\n\n**升环施法。** 使用 4 环及以上法术位时，法术位每比 3 环高一环，伤害增加 1d8。"
  },
  "spellHelp.native.stinking-cloud": {
    "en": "You create a 20-foot radius sphere of yellow, nauseating gas centered on a point within range. The cloud spreads around corners, and its area is heavily obscured. The cloud lingers in the air for the duration.\n\nEach creature that is completely within the cloud at the start of its turn must make a Constitution saving throw against poison. On a failed save, the creature spends its action that turn retching and reeling. Creatures that don't need to breathe or are immune to poison automatically succeed on this saving throw.\n\nA moderate wind (at least 10 miles per hour) disperses the cloud after 4 rounds. A strong wind (at least 20 miles per hour) disperses it after 1 round.",
    "zh-CN": "以施法距离内一点为中心，创造半径 20 英尺、黄色且令人作呕的气体球。云团绕过转角，区域为重度遮蔽，并在持续时间内停留空中。\n\n每个在自身回合开始时完全位于云中的生物，都进行对抗毒素的体质豁免。失败时，该回合的动作用于干呕和踉跄。不需要呼吸或免疫毒素的生物自动成功。\n\n中等强度风，至少每小时 10 英里，会在 4 轮后吹散云团。强风，至少每小时 20 英里，会在 1 轮后吹散。"
  },
  "spellHelp.native.tiny-hut": {
    "en": "A 10-foot radius immobile dome of force springs into existence around and above you and remains stationary for the duration. The spell ends if you leave its area.\n\nNine creatures of Medium size or smaller can fit inside the dome with you. The spell fails if its area includes a larger creature or more than nine creatures. Creatures and objects within the dome when you cast this spell can move through it freely. All other creatures and objects are barred from passing through it. Spells and other magical effects can't extend through the dome or be cast through it. The atmosphere inside the space is comfortable and dry, regardless of the weather outside.\n\nUntil the spell ends, you can command the interior to become dimly lit or dark. The dome is opaque from the outside, of any color you choose, but it is transparent from the inside.",
    "zh-CN": "半径 10 英尺、固定的力场穹顶在你周围与上方出现，在持续时间内保持原位。你离开区域时，法术结束。\n\n穹顶内可与你一起容纳九个中型或更小的生物。区域内有更大生物，或超过九个生物时，法术失败。施法时在穹顶内的生物与物体可自由穿过；其他生物与物体不能穿过。法术与其他魔法效果不能延伸或施放穿过穹顶。无论外面天气如何，内部空气始终舒适、干燥。\n\n法术结束前，可以命令内部变为微光或黑暗。穹顶从外面看不透明，颜色自选；从内部看则透明。"
  },
  "spellHelp.native.tongues": {
    "en": "This spell grants the creature you touch the ability to understand any spoken language it hears. Moreover, when the target speaks, any creature that knows at least one language and can hear the target understands what it says.",
    "zh-CN": "你触碰的生物获得理解所听见任何口头语言的能力。此外，目标说话时，任何至少懂一种语言、且能听见目标的生物都能理解。"
  },
  "spellHelp.native.vampiric-touch": {
    "en": "The touch of your shadow-wreathed hand can siphon life force from others to heal your wounds. Make a melee spell attack against a creature within your reach. On a hit, the target takes 3d6 necrotic damage, and you regain hit points equal to half the amount of necrotic damage dealt. Until the spell ends, you can make the attack again on each of your turns as an action.\n\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd.",
    "zh-CN": "你被阴影包裹的手，能汲取他人生命力来治疗自身伤口。对触及范围内一个生物进行近战法术攻击。命中时，目标受到 3d6 暗蚀伤害，你恢复等于实际造成暗蚀伤害一半的生命值。法术结束前，每个自身回合都可以用动作再次进行该攻击。\n\n**升环施法。** 使用 4 环及以上法术位时，法术位每比 3 环高一环，伤害增加 1d6。"
  },
  "spellHelp.native.water-breathing": {
    "en": "This spell grants up to ten willing creatures you can see within range the ability to breathe underwater until the spell ends. Affected creatures also retain their normal mode of respiration.",
    "zh-CN": "赋予施法距离内最多十个可见的自愿生物水下呼吸能力，持续至法术结束。受影响者也保留原有呼吸方式。"
  },
  "spellHelp.native.water-walk": {
    "en": "This spell grants the ability to move across any liquid surface-such as water, acid, mud, snow, quicksand, or lava-as if it were harmless solid ground (creatures crossing molten lava can still take damage from the heat). Up to ten willing creatures you can see within range gain this ability for the duration.\n\nIf you target a creature submerged in a liquid, the spell carries the target to the surface of the liquid at a rate of 60 feet per round.",
    "zh-CN": "使施法距离内最多十个可见的自愿生物，在持续时间内能将任何液体表面，例如水、强酸、泥浆、雪、流沙或熔岩，视为无害的坚实地面并在其上移动。穿过熔岩时，生物仍可能受到热量伤害。\n\n若目标生物浸没在液体中，法术以每轮 60 英尺的速度将其带到液面。"
  },
  "spellHelp.native.wind-wall": {
    "en": "A wall of strong wind rises from the ground at a point you choose within range. You can make the wall up to 50 feet long, 15 feet high, and 1 foot thick. You can shape the wall in any way you choose so long as it makes one continuous path along the ground. The wall lasts for the duration.\n\nWhen the wall appears, each creature within its area must make a Strength saving throw. A creature takes 3d8 bludgeoning damage on a failed save, or half as much damage on a successful one.\n\nThe strong wind keeps fog, smoke, and other gases at bay. Small or smaller flying creatures or objects can't pass through the wall. Loose, lightweight materials brought into the wall fly upward. Arrows, bolts, and other ordinary projectiles launched at targets behind the wall are deflected upward and automatically miss. (Boulders hurled by giants or siege engines, and similar projectiles, are unaffected.) Creatures in gaseous form can't pass through it.",
    "zh-CN": "一道强风之墙从施法距离内自选的一点拔地而起。最长 50 英尺、最高 15 英尺、厚 1 英尺。形状自选，只要沿地面形成一条连续路径；持续至法术结束。\n\n风墙出现时，区域内每个生物都进行力量豁免，失败时受到 3d8 钝击伤害，成功时一半。\n\n强风阻挡雾、烟与其他气体。小型或更小的飞行生物或物体无法穿过。进入墙中的松散轻质物料会被吹向上方。向墙后目标发射的箭、弩矢及其他普通投射物会被向上偏转，自动未命中；巨人或攻城器械投掷的巨石与类似投射物不受影响。气体形态的生物不能穿过。"
  }
});
